      if (want !== 0 && closeEnough(got, 1 / want)) return { tag: "reciprocal", say: "That's the reciprocal of the answer \u2014 the divide may be upside down." };
      if (closeEnough(got, want * 2)) return { tag: "double", say: "That's exactly twice the answer." };
      if (closeEnough(got, want / 2)) return { tag: "half", say: "That's exactly half the answer." };
      if (want > 0 && got > 0 && closeEnough(got, Math.sqrt(want))) return { tag: "root", say: "That's the square root of the answer \u2014 one squaring short." };
