          criterion: { kind: "numeric", value: rows * perRow - taken, tol: 1e-9 },
          steps: [step("First find how many there were: " + rows + " \u00D7 " + perRow + " = " + (rows * perRow) + "."),
          step("Then take away the ones used: " + (rows * perRow) + " \u2212 " + taken + " = " + (rows * perRow - taken) + "."),
          step("Stopping after the multiplication answers a question nobody asked.")],
          hints: ["Two things happen here \u2014 what has to be worked out first?", "Check what the question actually asks for at the end."]
