/* Can this skill be generated for at all?

   Measured, not assumed. The extractor reads 171 specific question shapes and
   refuses anything outside them rather than guessing — which is right, but it
   means only about a third of skills produce prompts it can read. Offering a
   button that always fails would be worse than not offering it, so the skill's
   OWN questions are put through the gate first. If the app cannot verify its
   own hand-built question, a proposed one has no chance either.

   Cheap enough to run on open: three builds, no network. */
function canGenerateFor(build, skillId) {
  // build(skillId, seed, difficulty) — seed first. Every difficulty is tried,
  // because a skill can be readable at one tier and not another.
  for (var d = 1; d <= 3; d++) {
    var q;
    try { q = build(skillId, 20260812 + d, d); } catch (e) { continue; }
    if (!q || !q.ask) continue;
    var a = answerTextOf(q.criterion);
    if (a === null) continue;
    var v;
    try { v = SOLVER.verify({ ask: q.ask, answer: a }); } catch (e) { continue; }
    if (v && v.accept) return true;
  }
  return false;
}

/* A question stores a test, not an answer, so the answer has to be recovered
   from the criterion to check the gate against it. Shapes the gate has no
   reading for return null, which is a refusal, not an error. */
function answerTextOf(c) {
  if (!c) return null;
  if (c.kind === "numeric") return String(c.value);
  if (c.kind === "equivalent") return typeof c.to === "string" ? c.to : S.print(c.to);
  if (c.kind === "setEqual") return Array.isArray(c.of) ? c.of.join(", ") : null;
  return null;
}

/* The prompt. The examples are not style guidance — they are the
   specification. The extractor reads exact phrasings, so a question worded
   freely is refused however good it is. The skill's own questions are already
   worded the way the extractor expects, which is why they are shown verbatim
   and why copying their shape is stated as the first rule. */
function generationPrompt(examples, count) {
  return [
    "Write " + count + " math practice questions.",
    "",
    "Return ONLY a JSON array. No prose, no markdown fences. Each element:",
    '  {"ask": "<the question, as plain text>", "answer": "<the answer>"}',
    "",
    "Copy the WORDING PATTERN of these examples exactly — same phrasing, same",
    "punctuation, same order of parts. Only the numbers should differ. A question",
    "worded differently will be discarded even if it is correct.",
    "",
    "Examples:",
    examples.map(function (e, i) { return (i + 1) + ". " + e; }).join("\n"),
    "",
    "Rules:",
    "- Change the numbers only. Do not add words, context, or a story.",
    "- Write math in plain text: x^2 for powers, * for multiply, / for divide, sqrt(9) for roots.",
    "- Give the exact answer, not a rounded one, unless the question asks for a rounding.",
    "- Do not repeat any example.",
    "- If you are not certain an answer is correct, leave that question out rather than guessing."
  ].join("\n");
}

/* Models wrap JSON in fences, or in a sentence, however firmly they are asked
   not to. Recover the array rather than discarding an otherwise fine batch. */
function readProposals(text) {
  if (!text) return [];
  let t = String(text).trim().replace(/^```(?:json)?/i, "").replace(/```$/, "").trim();
  const open = t.indexOf("["), close = t.lastIndexOf("]");
  if (open === -1 || close === -1 || close < open) return [];
  let arr;
  try { arr = JSON.parse(t.slice(open, close + 1)); } catch (e) { return []; }
  if (!Array.isArray(arr)) return [];
  return arr
    .filter(function (o) { return o && typeof o.ask === "string"; })
    .map(function (o) { return { ask: o.ask.trim(), answer: String(o.answer == null ? "" : o.answer).trim() }; });
}

/* Ask for `want` questions and return only those the solver confirmed.
   Over-asks, because discards are normal and expected; retries a bounded
   number of times; and reports honestly rather than padding a short batch. */
async function generatePractice(examples, want, opts) {
  const o = opts || {};
  const wanted = Math.max(1, Math.min(Number(want) || 3, 8));
  const maxRounds = o.rounds || 2;
  // opts.client is a seam for tests: it lets the whole loop — over-asking,
  // screening, retrying, reporting — run against a stand-in proposer without
  // a network. In the app it is never passed, so the real client is used.
  const sb = o.client || await genClient();
  if (!sb) return { ok: false, why: "Couldn't reach the question service.", kept: [], dropped: [] };

  const kept = [], dropped = [];
  const seen = Object.create(null);
  examples.forEach(function (e) { seen[String(e).replace(/\s+/g, " ").trim()] = true; });

  for (let round = 0; round < maxRounds && kept.length < wanted; round++) {
    // Ask for more than are needed: the gate is strict on purpose, so a batch
    // where everything survives is the exception rather than the target.
    const ask = Math.min(8, (wanted - kept.length) * 2);
    let data, error;
    try {
      const r = await sb.functions.invoke("ai", {
        body: { prompt: generationPrompt(examples, ask), model: AI_MODEL_HINT }
      });
      data = r.data; error = r.error;
    } catch (e) {
      return { ok: false, why: "Couldn't reach the question service.", kept: kept, dropped: dropped };
    }
    const said = data && data.error;
    if (said) return { ok: false, why: said, kept: kept, dropped: dropped };
    if (error) return { ok: false, why: error.message || "The request failed.", kept: kept, dropped: dropped };

    const proposals = readProposals(data && data.text).filter(function (p) {
      const k = p.ask.replace(/\s+/g, " ").trim();
      if (seen[k]) return false;              // no duplicates, of each other or the examples
      seen[k] = true;
      return true;
    });
    if (!proposals.length) { dropped.push({ ask: "(batch)", why: "nothing readable came back" }); continue; }

    const screened = SOLVER.screen(proposals);
    screened.kept.forEach(function (q) { if (kept.length < wanted) kept.push(q); });
    screened.dropped.forEach(function (d) { dropped.push(d); });
  }

  return {
    ok: kept.length > 0,
    kept: kept,
    dropped: dropped,
    why: kept.length ? null
      : "None of the questions could be checked, so none are being shown."
  };
}

/* ===========================================================================
   PLACEMENT

   "Where am I?" — answered by asking, not by guessing from a birthday.

   The prerequisite graph does the work. 180 of the 182 skills declare what
   they need first, so a wrong answer is informative twice over: it says this
   skill isn't secure, and it makes everything downstream of it a poor thing to
   ask about next. That is what keeps this to roughly twenty questions instead
   of a hundred and eighty.

   WHAT IT REPORTS, AND WHY NOT A GRADE LEVEL

   A single number would be a lie. Nobody is uniformly "Year 9" — you can be
   fluent at algebra and shaky on circle theorems in the same afternoon, and
   averaging those into one label hides exactly the thing worth knowing. So the
   output is a FRONTIER: the skills whose prerequisites you have but which you
   don't yet, which is also the honest answer to "what should I do next".

   WHAT IT WILL NOT DO

   It will not invent a skill to fill a gap. A generated question can be
   checked by the solver before anyone sees it; a generated SKILL cannot —
   it would carry teaching, method tiers and prerequisites that nothing has
   verified, and a wrong one corrupts the graph rather than one question. Where
   the test finds a gap the curriculum doesn't cover, it says so and leaves it
   to be authored deliberately.

   HOW THE ANSWERS ARE JUDGED

   By the same criterion the practice screen uses. No separate marking path
   exists here, because two ways of deciding "correct" is one too many.
   =========================================================================== */

/* Depth in the graph: how many prerequisites deep a skill sits. Cheap to
   compute, and it stands in for "how advanced" without anyone having to
   hand-label a year group onto every skill. */
function skillDepth(id, byId, seen) {
  const sk = byId[id];
  if (!sk) return 0;
  seen = seen || {};
  if (seen[id]) return 0;              // a cycle would otherwise recurse forever
  seen[id] = true;
  const needs = sk.needs || [];
  if (!needs.length) return 0;
  let deepest = 0;
  for (let i = 0; i < needs.length; i++) {
    const d = skillDepth(needs[i], byId, seen);
    if (d + 1 > deepest) deepest = d + 1;
  }
  return deepest;
}

/* Everything this skill rests on, all the way down. */
function allPrereqs(id, byId, out, seen) {
  out = out || {}; seen = seen || {};
  if (seen[id]) return out;
  seen[id] = true;
  const needs = (byId[id] && byId[id].needs) || [];
  for (let i = 0; i < needs.length; i++) { out[needs[i]] = true; allPrereqs(needs[i], byId, out, seen); }
  return out;
}

/* Everything that rests on this skill. */
function dependents(id, skills) {
  const direct = skills.filter(function (s) { return (s.needs || []).indexOf(id) !== -1; });
  const out = {};
  direct.forEach(function (s) {
    out[s.id] = true;
    const deeper = dependents(s.id, skills);
    for (const k in deeper) out[k] = true;
  });
  return out;
}

/* A placement run.

   Not a fixed list of questions. After each answer the next skill is chosen to
   be the most informative one left — roughly the middle of what is still
   unknown — so the test converges instead of grinding through a syllabus. */
function startPlacement(skills, byId, opts) {
  const o = opts || {};
  const max = o.maxQuestions || 20;
  const state = {
    known: {},        // id -> true (got it) / false (didn't)
    asked: [],
    max: max,
    depth: {},
  };
  skills.forEach(function (s) { state.depth[s.id] = skillDepth(s.id, byId); });
  return state;
}

/* Which skills are still worth asking about: not yet known either way, and
   not already settled by inference. */
function candidates(state, skills) {
  return skills.filter(function (s) { return state.known[s.id] === undefined; });
}

/* Choose the next question.

   Binary search over depth. If the last answer was right, go deeper; if it was
   wrong, go shallower. Starting in the middle rather than at the bottom is
   what makes twenty questions enough — beginning at "counting" would waste
   half the test on skills nobody was in doubt about. */
function nextSkill(state, skills, byId) {
  if (state.asked.length >= state.max) return null;
  const left = candidates(state, skills);
  if (!left.length) return null;

  const depths = left.map(function (s) { return state.depth[s.id]; });
  const lo = Math.min.apply(null, depths), hi = Math.max.apply(null, depths);
  let target;
  if (!state.asked.length) target = Math.round((lo + hi) / 2);
  else {
    const last = state.asked[state.asked.length - 1];
    const lastDepth = state.depth[last.id];
    target = state.known[last.id] ? lastDepth + Math.max(1, Math.round((hi - lastDepth) / 2))
                                  : lastDepth - Math.max(1, Math.round((lastDepth - lo) / 2));
  }
  target = Math.max(lo, Math.min(hi, target));

  // Nearest to the target depth; ties broken by breadth, so the test spreads
  // across strands instead of drilling one corner of the syllabus.
  const seenStrands = {};
  state.asked.forEach(function (a) { seenStrands[byId[a.id].strand] = (seenStrands[byId[a.id].strand] || 0) + 1; });
  left.sort(function (a, b) {
    const da = Math.abs(state.depth[a.id] - target), db = Math.abs(state.depth[b.id] - target);
    if (da !== db) return da - db;
    return (seenStrands[a.strand] || 0) - (seenStrands[b.strand] || 0);
  });
  return left[0];
}

/* Record an answer, and infer everything it implies.

   Right on a skill means its prerequisites are secure — you cannot factorise
   without multiplying. Wrong means everything built on top is not yet worth
   asking about. Inference is marked separately from evidence so the report can
   be honest about which is which. */
function recordAnswer(state, skillId, correct, skills, byId) {
  state.known[skillId] = !!correct;
  state.asked.push({ id: skillId, correct: !!correct });
  if (correct) {
    const below = allPrereqs(skillId, byId);
    for (const id in below) if (state.known[id] === undefined) state.known[id] = true;
  } else {
    const above = dependents(skillId, skills);
    for (const id in above) if (state.known[id] === undefined) state.known[id] = false;
  }
  return state;
}

/* The report.

   `frontier` is the useful part: skills whose prerequisites are all secure but
   which are not themselves secure. That is precisely "ready to learn next".

   `unknown` is stated rather than hidden. A twenty-question test cannot settle
   182 skills, and pretending otherwise would be the same kind of lie as a
   single grade level. */
function placementReport(state, skills, byId) {
  const secure = [], shaky = [], unknown = [];
  skills.forEach(function (s) {
    if (state.known[s.id] === true) secure.push(s.id);
    else if (state.known[s.id] === false) shaky.push(s.id);
    else unknown.push(s.id);
  });

  /* Ready to try next: everything it rests on is secure, and it is not itself
     secure. That includes skills the test never reached — an earlier version
     counted only the ones answered wrongly, and a learner who happened not to
     be asked about their own frontier got told nothing at all, which is the
     one thing this screen exists to avoid.

     `sure` marks which is which: a skill answered wrongly is evidence, a skill
     never reached is a reasonable next step but not a finding. */
  const notSecure = shaky.concat(unknown);
  const frontier = notSecure.filter(function (id) {
    const needs = (byId[id] && byId[id].needs) || [];
    if (!needs.length) return false;            // a root nobody was asked about isn't a frontier
    return needs.every(function (n) { return state.known[n] === true; });
  }).sort(function (a, b) {
    // shallowest first: the nearest thing to what they can already do
    return state.depth[a] - state.depth[b];
  });
  const frontierEvidence = {};
  frontier.forEach(function (id) { frontierEvidence[id] = state.known[id] === false ? "tested" : "inferred"; });

  // Per strand, the deepest skill actually shown to be secure. Ten honest
  // numbers instead of one dishonest one.
  const byStrand = {};
  skills.forEach(function (s) {
    if (state.known[s.id] !== true) return;
    const d = state.depth[s.id];
    if (!byStrand[s.strand] || d > byStrand[s.strand].depth) byStrand[s.strand] = { id: s.id, name: s.name, depth: d };
  });

  return {
    asked: state.asked.length,
    evidence: state.asked.slice(),
    secure: secure, shaky: shaky, unknown: unknown,
    frontier: frontier,
    frontierEvidence: frontierEvidence,
    reach: byStrand,
    // Said plainly so no screen has to imply otherwise.
    caveat: state.asked.length + " questions can't settle " + skills.length +
      " skills. " + unknown.length + " weren't reached either way, and nothing here claims they were."
  };
}

/* --------------------------------- CSS -------------------------------- */
const CSS = `
.colsum{display:flex;justify-content:center;margin:10px 0}
.colsum pre{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:22px;
  line-height:1.35;font-weight:700;color:var(--ink);margin:0;letter-spacing:.06em}
.colsum .colop{color:var(--a)}
.colsum .colrule{color:var(--a)}
.circw{display:block;margin:6px auto;max-width:180px;height:auto}

/* Cloud sign-in fields. Full width and body-sized; everything else about them
   is whatever the app already uses for an input. */
input.cloudin{display:block;width:100%;margin-top:var(--s2);padding:11px 13px;
  border:1px solid var(--line);border-radius:var(--r-lg);background:var(--card-2);
  color:var(--ink);font-family:inherit;font-size:15px;font-weight:600}
input.cloudin:focus{outline:none;border-color:var(--a)}

/* Generated practice. Visually quieter than the hand-written flow on purpose:
   it is an extra, not the main path, and the confirmation line matters more
   than the styling. */
.genpanel{margin-top:18px;padding-top:16px;border-top:1px solid var(--line)}
.gennote{font-size:13px;color:var(--ink-faint)}
.gentitle{font-size:13px;font-weight:700;color:var(--ink);margin-bottom:4px}
.genwhy{font-size:12.5px;color:var(--ink-faint);line-height:1.5;margin-bottom:6px}
.genfail{padding:12px 14px;border:1px solid var(--line);border-radius:12px;background:var(--card-2)}
.genlist{display:flex;flex-direction:column;gap:8px}
.genitem{display:flex;flex-direction:column;align-items:flex-start;gap:3px;width:100%;
  padding:11px 13px;border:1px solid var(--line);border-radius:12px;background:var(--card);
  font-family:inherit;cursor:pointer;text-align:left;transition:.15s}
.genitem:hover{border-color:var(--a);background:var(--a-tint)}
.genask{font-size:15px;font-weight:650;color:var(--ink)}
.genconf{font-size:11.5px;color:var(--ink-faint)}

/* ==========================================================================
     SLATE — the design system.

     The subject decides the design. Mathematics is set in serif in every
     textbook ever printed, so expressions and headings are set in serif here
     too; the interface around them is a plain, precise sans. The only place
     anything is hand-drawn is the working surface, because that is the only
     thing a person would actually have drawn.

     Everything else is discipline: one accent used sparingly, hairline rules
     instead of heavy shadow, a fixed type scale, and a four-point spacing
     rhythm. Hierarchy comes from weight and space rather than from color.
     ========================================================================== */

  :root{
    --paper:#f3f5f5; --card:#ffffff; --card-2:#eaeeee; --card-3:#f7f9f9;
    --ink:#172123; --ink-soft:#5a6b6e; --ink-faint:#8d9ea1;
    --line:#dfe5e5; --line-strong:#c9d3d3;

    --a:#0e6f66; --a-tint:#e1efed; --a-deep:#0a5850;

    --ok:#0f7a63; --ok-bg:#e4f2ee; --ok-ink:#0a5343;
    --no:#b3323d; --no-bg:#fbeaeb; --no-ink:#8a2530;
    --hm:#96590a; --hm-bg:#fbf1de; --hm-ink:#6f4207;

    --chalk:#46595c;

    /* Every face in this stack has lining figures. Georgia is deliberately
       absent: its numerals are old-style and hop above and below the baseline,
       which is fine in prose and wrong in an equation. */
    --serif:ui-serif,"New York","Iowan Old Style","Palatino Linotype",Palatino,
      Cambria,"Times New Roman",Times,serif;
    --sans:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    --mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
    --t-hero:30px; --t-h2:22px; --t-h3:18px; --t-body:15.5px;
    --t-sm:13.5px; --t-xs:12.25px; --t-cap:11px;
    /* display sizes, for the places where mathematics is the object rather
       than the description: the question, the answer, the session score */
    --t-q:26px; --t-q-sm:21px; --t-input:20px; --t-score:42px;
    /* the handwritten working, set in monospace so columns line up */
    --t-paper:12.5px;

    --s1:4px; --s2:8px; --s3:12px; --s4:16px; --s5:24px; --s6:34px;
    --r-sm:9px; --r-md:12px; --r-lg:15px;

    --shadow:0 1px 2px rgba(23,33,35,.05), 0 6px 18px rgba(23,33,35,.06);
    --shadow-lift:0 -10px 34px rgba(23,33,35,.16);
    --tabh:58px;
  }

  *{box-sizing:border-box}
  html,body{margin:0;padding:0}
  body{
    background:var(--paper); color:var(--ink);
    font:var(--t-body)/1.55 var(--sans);
    -webkit-font-smoothing:antialiased; text-rendering:optimizeLegibility;
    font-variant-numeric:lining-nums tabular-nums;
  }
  button{color:inherit;font-family:inherit}

  /* The scrolling element is .scroll, and it has to genuinely be one.
     "overflow-x:hidden" alone already made overflow-y compute to auto, so it
     became a scroll container \u2014 but .app only had min-height, so .scroll never
     actually overflowed and the BODY scrolled instead. Wheel events then hit a
     scroll container that could not move, and overscroll-behavior:contain
     stopped them chaining out to the body, so only dragging the scrollbar
     worked. Fixing the height makes .scroll own its scrolling for real. */
  html,body{height:100%}
  .app{max-width:600px;margin:0 auto;height:100vh;height:100dvh;
    display:flex;flex-direction:column;overflow:hidden;
    -webkit-tap-highlight-color:transparent}
  .app.tabbed .scroll{padding-bottom:calc(var(--tabh) + var(--s6) + env(safe-area-inset-bottom))}
  .scroll{flex:1 1 auto;min-height:0;padding:var(--s4) var(--s4) var(--s6);
    overflow-y:auto;overflow-x:hidden;
    -webkit-overflow-scrolling:touch;overscroll-behavior-y:contain}
  button,.tab,.sdoor,.key,.lpip,.seg{-webkit-user-select:none;user-select:none;touch-action:manipulation}
  :focus-visible{outline:2px solid var(--a);outline-offset:2px;border-radius:4px}

  .scroll.fwd{animation:pushIn .24s cubic-bezier(.22,.7,.3,1)}
  .scroll.back{animation:popIn .24s cubic-bezier(.22,.7,.3,1)}
  .scroll.fade{animation:fadeIn .2s ease}
  @keyframes pushIn{from{opacity:.5;transform:translateX(16px)}to{opacity:1;transform:none}}
  @keyframes popIn{from{opacity:.5;transform:translateX(-16px)}to{opacity:1;transform:none}}
  @keyframes fadeIn{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
  @keyframes fade{from{opacity:0}to{opacity:1}}
  .screen{animation:fadeIn .22s ease}
  @media (prefers-reduced-motion:reduce){
    .scroll.fwd,.scroll.back,.scroll.fade,.screen,.sheet,.toast,.ccell.lit{animation:none}
  }

  .appbar{position:sticky;top:0;z-index:20;padding-top:env(safe-area-inset-top);
    background:rgba(243,245,245,.88);
    -webkit-backdrop-filter:saturate(1.3) blur(14px);backdrop-filter:saturate(1.3) blur(14px);
    display:flex;align-items:center;gap:var(--s3);
    padding-left:var(--s4);padding-right:var(--s4);
    border-bottom:1px solid var(--line);min-height:52px}
  .appbar .mk{width:26px;height:26px;border-radius:7px;background:var(--a);color:#fff;
    display:flex;align-items:center;justify-content:center;flex:0 0 auto}
  .appbar .ti{font-family:var(--serif);font-size:var(--t-h3);font-weight:600;letter-spacing:-.01em}
  .navback{background:none;border:none;color:var(--ink-soft);cursor:pointer;
    display:flex;align-items:center;justify-content:center;width:40px;height:40px;
    min-height:40px;flex:0 0 auto;border-radius:var(--r-sm);margin-left:-9px}
  .navback:active{background:var(--card-2)}

  .tabbar{position:fixed;left:0;right:0;bottom:0;z-index:60;display:flex;
    background:rgba(243,245,245,.93);
    -webkit-backdrop-filter:saturate(1.4) blur(16px);backdrop-filter:saturate(1.4) blur(16px);
    border-top:1px solid var(--line);padding-bottom:env(safe-area-inset-bottom);
    max-width:600px;margin:0 auto}
  .tab{flex:1;background:none;border:none;display:flex;flex-direction:column;align-items:center;
    justify-content:center;gap:3px;height:var(--tabh);color:var(--ink-faint);cursor:pointer;
    font-size:var(--t-cap);font-weight:600;transition:color .14s ease}
  .tab.on{color:var(--a)}
  .tab:active{opacity:.6}
  .tab span{line-height:1}

  .hero{margin:var(--s3) 0 var(--s5)}
  .hero h1{font-family:var(--serif);font-size:var(--t-hero);font-weight:600;
    letter-spacing:-.02em;margin:0 0 var(--s2);line-height:1.12}
  .hero p{color:var(--ink-soft);font-size:var(--t-sm);margin:0;max-width:46ch;line-height:1.6}
  .secttl{font-size:var(--t-cap);font-weight:700;letter-spacing:.09em;text-transform:uppercase;
    color:var(--ink-faint);margin:var(--s5) 2px var(--s3)}

  .searchrow{position:relative;margin:0 0 var(--s4)}
  .search{width:100%;font-size:var(--t-body);padding:11px 36px 11px var(--s3);
    border-radius:var(--r-md);border:1px solid var(--line);background:var(--card);
    color:var(--ink);font-family:inherit;font-weight:450}
  .search::placeholder{color:var(--ink-faint)}
  .search:focus{outline:none;border-color:var(--a);box-shadow:0 0 0 3px var(--a-tint)}
  .clearq{position:absolute;right:4px;top:50%;transform:translateY(-50%);width:38px;height:38px;
    min-height:38px;border:none;background:none;color:var(--ink-faint);font-size:var(--t-h3);
    cursor:pointer;border-radius:50%}
  .nores{font-size:var(--t-sm);color:var(--ink-soft);padding:var(--s5) 2px;line-height:1.6}

  .cont{display:block;width:100%;text-align:left;background:var(--card);
    border:1px solid var(--line);border-left:2px solid var(--a);
    border-radius:var(--r-lg);padding:var(--s4);cursor:pointer;margin-bottom:var(--s2);
    transition:border-color .14s ease}
  .cont:hover{border-color:var(--line-strong);border-left-color:var(--a)}
  .cont:active{background:var(--card-3)}
  .ct1{font-size:var(--t-cap);font-weight:700;text-transform:uppercase;letter-spacing:.09em;color:var(--a)}
  .ct2{font-family:var(--serif);font-size:var(--t-h3);font-weight:600;margin-top:var(--s1);letter-spacing:-.01em}
  .ct3{font-size:var(--t-sm);color:var(--ink-soft);margin-top:3px;line-height:1.55}
  .cont.due{border-left-color:var(--hm)}
  .cont.due .ct1{color:var(--hm)}
  .cont.alt{border-left-color:var(--line-strong)}
  .cont.alt .ct1{color:var(--ink-faint)}

  .grid{display:grid;grid-template-columns:1fr 1fr;gap:var(--s2)}
  @media (max-width:420px){.grid{grid-template-columns:1fr}}
  .skill{text-align:left;background:var(--card);border:1px solid var(--line);
    border-radius:var(--r-lg);padding:var(--s3) var(--s3) var(--s2);
    display:flex;flex-direction:column;transition:border-color .14s ease}
  .skill:hover{border-color:var(--line-strong)}
  .skill.started{border-left:2px solid var(--a);padding-left:calc(var(--s3) - 1px)}
  .sname{font-family:var(--serif);font-size:var(--t-h3);font-weight:600;letter-spacing:-.01em;line-height:1.25}
  .smeta{font-size:var(--t-xs);color:var(--ink-faint);margin-top:3px;line-height:1.45}
  .smeth{font-size:var(--t-cap);color:var(--ink-soft);margin-top:var(--s2);line-height:1.45;
    padding-top:var(--s2);border-top:1px solid var(--line)}
  .sbar{height:3px;border-radius:99px;background:var(--card-2);margin-top:var(--s2);overflow:hidden}
  .sbar i{display:block;height:100%;background:var(--a);border-radius:99px}
  .sdoors{display:flex;gap:var(--s1);margin-top:var(--s3)}
  .sdoor{flex:1;background:var(--card);border:1px solid var(--line);border-radius:var(--r-sm);
    padding:var(--s2) 6px;font-size:var(--t-xs);font-weight:600;cursor:pointer;min-height:38px;
    color:var(--ink-soft);transition:background .14s ease,color .14s ease}
  .sdoor:hover{background:var(--card-2);color:var(--ink)}
  .sdoor.go{background:var(--a);border-color:var(--a);color:#fff}
  .sdoor.go:hover{background:var(--a-deep)}

  .qcard{background:var(--card);border:1px solid var(--line);border-radius:var(--r-lg);
    padding:var(--s5) var(--s4) var(--s4);text-align:center}
  .qskill{font-size:var(--t-cap);font-weight:700;letter-spacing:.09em;text-transform:uppercase;
    color:var(--ink-faint)}
  .qask{font-family:var(--serif);font-size:var(--t-q);font-weight:500;margin:var(--s3) 0 var(--s1);
    line-height:1.35;letter-spacing:-.01em;font-variant-numeric:lining-nums tabular-nums}

  .widget{display:block;width:100%;max-width:330px;margin:var(--s4) auto var(--s1);height:auto;overflow:visible}
  .chalk{stroke:var(--chalk);stroke-linecap:round;opacity:.8}
  .cline{stroke:var(--a);opacity:1}
  .clab{fill:var(--ink-soft);font-size:var(--t-cap);text-anchor:middle;font-weight:600;font-family:var(--sans)}
  .clab.strong{fill:var(--ink);font-size:var(--t-xs)}
  .clab.pick{fill:var(--a)}
  .cdot{fill:var(--chalk)}
  .cdot.pick{fill:var(--a)}
  .cjump{stroke:var(--a);stroke-width:1.6;stroke-dasharray:3 4;opacity:.85}
  .cbox{fill:none;stroke:var(--chalk);stroke-width:1.4;opacity:.55}
  .ccell{fill:var(--a-tint);stroke:var(--a);stroke-width:.6;opacity:.5;rx:1}
  .ccell.lit{animation:lit .45s ease both}
  @keyframes lit{from{opacity:.12}to{opacity:.85}}
  .cpart{fill:var(--card-2);stroke:var(--chalk);stroke-width:1.1;opacity:.9}
  .cpart.on{fill:var(--a-tint);stroke:var(--a)}
  .cpart.add{fill:var(--ok-bg);stroke:var(--ok)}
  .cx{fill:var(--a);opacity:.85;rx:2}
  .cx.negx{fill:var(--no)}
  .cu{fill:var(--chalk);opacity:.65}
  .cu.neg{fill:var(--no)}
  .cgrid{stroke:var(--line);stroke-width:1}
  .ccurve{stroke:var(--chalk);stroke-width:1.8;opacity:.7}
  .ccirc{fill:none;stroke:var(--chalk);stroke-width:1.5;opacity:.7}
  .cdash{stroke:var(--a);stroke-width:1.2;stroke-dasharray:3 3;opacity:.75}
  .moves{display:flex;flex-wrap:wrap;gap:var(--s1);justify-content:center;margin-top:var(--s2)}
  .mv{background:var(--card);border:1px solid var(--line);border-radius:var(--r-sm);
    padding:var(--s2) var(--s3);font-size:var(--t-sm);font-weight:600;cursor:pointer;min-height:38px}
  .mv:hover{border-color:var(--a);color:var(--a)}
  .mv.ghost{background:none;color:var(--ink-faint);border-style:dashed}

  .ansbox{margin-top:var(--s4)}
  .ansrow{display:flex;gap:var(--s2)}
  .ans{flex:1;font-family:var(--serif);font-size:var(--t-input);padding:12px var(--s3);
    border-radius:var(--r-md);border:1px solid var(--line);background:var(--card);color:var(--ink);
    font-weight:500;min-width:0;font-variant-numeric:lining-nums tabular-nums}
  .ans::placeholder{font-family:var(--sans);font-size:var(--t-body);color:var(--ink-faint)}
  .ans:focus{outline:none;border-color:var(--a);box-shadow:0 0 0 3px var(--a-tint)}
  .del{width:48px;min-height:48px;border-radius:var(--r-md);border:1px solid var(--line);
    background:var(--card);font-size:var(--t-body);cursor:pointer;color:var(--ink-soft)}
  .del:hover{border-color:var(--line-strong)}
  .reading{font-size:var(--t-xs);color:var(--ink-faint);margin:var(--s2) 2px 0;font-weight:500;font-family:var(--serif)}
  .reading.bad{color:var(--hm);font-family:var(--sans)}
  .keys{display:grid;grid-template-columns:repeat(6,1fr);gap:5px;margin-top:var(--s2)}
  .key{background:var(--card);border:1px solid var(--line);border-radius:var(--r-sm);
    padding:10px 0;font-family:var(--serif);font-size:var(--t-body);font-weight:500;cursor:pointer;min-height:42px}
  .key:active{background:var(--a-tint);border-color:var(--a)}

  .btn{width:100%;font-size:var(--t-body);font-weight:600;cursor:pointer;border-radius:var(--r-md);
    padding:13px;min-height:48px;border:1px solid var(--line);background:var(--card);
    color:var(--ink);margin-top:var(--s3);transition:background .14s ease,border-color .14s ease}
  .btn:hover{border-color:var(--line-strong)}
  .btn.primary{background:var(--a);border-color:var(--a);color:#fff}
  .btn.primary:hover{background:var(--a-deep);border-color:var(--a-deep)}
  .btn.danger{background:var(--card);border-color:var(--no);color:var(--no)}
  .btn.danger:hover{background:var(--no);color:#fff}
  .btn:disabled{opacity:.4;cursor:default}
  .btn:disabled:hover{border-color:var(--line);background:var(--card)}
  .linkbtn{background:none;border:none;color:var(--ink-faint);font:inherit;font-size:var(--t-sm);
    cursor:pointer;padding:var(--s3);min-height:42px;display:block;margin:var(--s1) auto 0;
    text-decoration:underline;text-underline-offset:3px}
  .linkbtn:hover{color:var(--ink-soft)}

  .verdict{margin-top:var(--s3);border-radius:var(--r-md);padding:var(--s3) var(--s4);
    font-size:var(--t-body);font-weight:600;border:1px solid var(--line);background:var(--card);
    border-left-width:2px}
  .verdict.good{background:var(--ok-bg);border-color:var(--ok);color:var(--ok-ink)}
  .verdict.bad{background:var(--no-bg);border-color:var(--no);color:var(--no-ink)}
  .verdict.hm{background:var(--hm-bg);border-color:var(--hm);color:var(--hm-ink)}
  .nearmiss{font-size:var(--t-sm);font-weight:450;margin-top:var(--s1);line-height:1.55}
  .vsub{font-size:var(--t-xs);font-weight:450;margin-top:var(--s1);opacity:.85}
  .workback{margin-top:var(--s2);font-size:var(--t-sm);color:var(--ink-soft);padding:0 2px}

  .teach,.steps{margin-top:var(--s4);background:var(--card);border:1px solid var(--line);
    border-radius:var(--r-lg);padding:var(--s4)}
  .teachlab{font-size:var(--t-cap);font-weight:700;text-transform:uppercase;letter-spacing:.09em;
    color:var(--ink-faint);margin-bottom:var(--s2)}
  .teach p{margin:0;font-size:var(--t-body);line-height:1.68}
  .stp{display:flex;gap:var(--s3);font-size:var(--t-sm);padding:6px 0;line-height:1.6}
  .stpbody{min-width:0;flex:1}
  .paper.inline{margin-top:var(--s2);display:inline-block;min-width:min(100%, 220px)}
  .sn{flex:0 0 auto;width:19px;height:19px;border-radius:5px;background:var(--card-2);
    color:var(--ink-soft);font-size:var(--t-cap);font-weight:700;display:flex;
    align-items:center;justify-content:center;align-self:flex-start;margin-top:2px}

  /* On a phone these stack, as everything does. Given room, the worked example
     sits BESIDE the idea so you can read the reasoning and the working together
     rather than scrolling between them. */
  .sidebyside{display:grid;gap:var(--s3);align-items:start}
  @media (min-width:780px){
    .sidebyside{grid-template-columns:1fr 1fr;gap:var(--s4)}
    .sidebyside > * { margin-top:var(--s4) }
  }

  .defs{margin-top:var(--s2);background:var(--card);border:1px solid var(--line);
    border-radius:var(--r-lg);padding:var(--s4)}
  .defs dl{margin:0}
  .defrow{padding:var(--s2) 0}
  .defrow + .defrow{border-top:1px solid var(--line)}
  .defs dt{font-family:var(--serif);font-size:var(--t-h3);font-weight:600;line-height:1.3}
  .defs dd{margin:2px 0 0;font-size:var(--t-sm);color:var(--ink-soft);line-height:1.6}

  .worked{margin-top:var(--s4);background:var(--card);border:1px solid var(--line);
    border-left:2px solid var(--a);border-radius:var(--r-lg);padding:var(--s4)}
  .wline-ex{display:grid;grid-template-columns:19px 1fr;gap:var(--s3);
    padding:var(--s3) 0;align-items:start}
  @media (min-width:560px){
    .wline-ex{grid-template-columns:19px 1fr minmax(140px, 40%)}
  }
  .wbody{min-width:0}
  /* The paper: what someone would actually have written at this point. Monospace
     and pre-wrapped, because the alignment of the columns IS the method. */
  .paper{margin:0;font-family:var(--mono);font-size:var(--t-paper);line-height:1.45;
    white-space:pre;overflow-x:auto;background:var(--card-3);color:var(--ink);
    border:1px solid var(--line);border-radius:var(--r-sm);padding:var(--s3);
    grid-column:2 / -1}
  @media (min-width:560px){ .paper{grid-column:3} }
  .wline-ex + .wline-ex{border-top:1px solid var(--line)}
  .wn{flex:0 0 auto;width:19px;height:19px;border-radius:5px;background:var(--a-tint);
    color:var(--a);font-size:var(--t-cap);font-weight:700;display:flex;align-items:center;
    justify-content:center;margin-top:3px}
  .wdoes{font-family:var(--serif);font-size:var(--t-h3);line-height:1.45;
    font-variant-numeric:lining-nums tabular-nums}
  .wwhy{font-size:var(--t-sm);color:var(--ink-soft);line-height:1.6;margin-top:3px}

  .hints{margin-top:var(--s3)}
  .hintbtn{width:100%;background:none;border:1px dashed var(--line-strong);border-radius:var(--r-md);
    padding:var(--s3);font-size:var(--t-sm);font-weight:600;color:var(--ink-soft);
    cursor:pointer;min-height:44px}
  .hintbtn:hover{border-color:var(--a);color:var(--a)}
  .hintbtn:disabled{opacity:.5;cursor:default}
  .rung{margin-top:var(--s2);background:var(--card);border:1px solid var(--line);
    border-left:2px solid var(--a);border-radius:var(--r-md);padding:var(--s3);
    font-size:var(--t-sm);line-height:1.6}
  .rung.answer{border-left-color:var(--hm)}
  .rl{font-size:var(--t-cap);font-weight:700;text-transform:uppercase;letter-spacing:.09em;
    color:var(--ink-faint);margin-bottom:3px}

  .worktoggle{margin:var(--s4) 2px 0}
  /* The label is the tap target, not the 17px box inside it. */
  .tgl{display:flex;align-items:center;gap:var(--s2);font-size:var(--t-sm);font-weight:600;
    cursor:pointer;min-height:44px}
  .tgl input{width:17px;height:17px;accent-color:var(--a)}
  .tglnote{display:block;font-size:var(--t-xs);color:var(--ink-faint);margin:3px 0 0 25px;line-height:1.5}
  .work{margin-top:var(--s3);background:var(--card);border:1px solid var(--line);
    border-radius:var(--r-lg);padding:var(--s3)}
  .worklab{font-size:var(--t-cap);font-weight:700;text-transform:uppercase;letter-spacing:.09em;
    color:var(--ink-faint);margin-bottom:var(--s2)}
  .wrow{display:flex;align-items:center;gap:var(--s2);margin-bottom:5px}
  .wmark{width:16px;text-align:center;font-weight:700;font-size:var(--t-sm);flex:0 0 auto;color:var(--ink-faint)}
  .wmark.ok{color:var(--ok)}
  .wmark.no{color:var(--no)}
  .wmark.hm{color:var(--hm)}
  .wmark.warn{color:var(--hm)}
  .wline{flex:1;font-family:var(--serif);font-size:var(--t-h3);padding:9px var(--s3);
    border-radius:var(--r-sm);border:1px solid var(--line);background:var(--card-3);
    color:var(--ink);font-weight:500;min-width:0;font-variant-numeric:lining-nums tabular-nums}
  .wline::placeholder{font-family:var(--sans);font-size:var(--t-sm);color:var(--ink-faint)}
  .wline:focus{outline:none;border-color:var(--a);background:var(--card);box-shadow:0 0 0 3px var(--a-tint)}
  .wnote{font-size:var(--t-xs);color:var(--hm);margin-top:var(--s2);font-weight:500;line-height:1.5}
  .wnote.good{color:var(--ok)}
  .wnote.warn{color:var(--hm)}

  .lhead{margin:var(--s2) 0 var(--s4)}
  .lskill{font-size:var(--t-cap);font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--ink-faint)}
  .lhead h2{font-family:var(--serif);font-size:var(--t-h2);font-weight:600;margin:var(--s1) 0 var(--s3);letter-spacing:-.015em}
  .lsteps{display:flex;flex-wrap:wrap;gap:5px}
  .lpip{background:var(--card);border:1px solid var(--line);border-radius:999px;
    padding:7px var(--s3);font-size:var(--t-xs);font-weight:600;color:var(--ink-soft);
    cursor:pointer;min-height:34px}
  .lpip:hover{border-color:var(--line-strong)}
  .lpip.on{background:var(--a);border-color:var(--a);color:#fff}
  .lwhy{background:var(--hm-bg);border:1px solid var(--hm);border-left-width:2px;
    border-radius:var(--r-md);padding:var(--s3);font-size:var(--t-sm);line-height:1.6;
    margin-bottom:var(--s3);color:var(--hm-ink)}
  .lwhy span{display:block;font-size:var(--t-cap);font-weight:700;text-transform:uppercase;
    letter-spacing:.09em;color:var(--hm);margin-bottom:3px}
  .guided{margin-top:var(--s4);background:var(--card);border:1px solid var(--a);
    border-radius:var(--r-lg);padding:var(--s4)}
  .guided .qask{font-size:var(--t-q-sm);margin:var(--s2) 0 2px}

  .sessbar{display:flex;justify-content:space-between;align-items:baseline;
    font-size:var(--t-xs);font-weight:600;color:var(--ink-faint);margin-bottom:var(--s2)}
  .sstier{color:var(--a);font-weight:700}
  .sessdots{display:flex;gap:3px;margin-bottom:var(--s4)}
  .sessdots i{flex:1;height:2px;border-radius:99px;background:var(--card-2)}
  .sessdots i.on{background:var(--a)}
  .sessend{text-align:center;padding:var(--s6) var(--s3)}
  .sessend h2{font-family:var(--serif);font-size:var(--t-score);margin:0 0 var(--s2);letter-spacing:-.03em;font-weight:600}
  .sessend p{color:var(--ink-soft);font-size:var(--t-sm);margin:0 auto var(--s2);max-width:36ch;line-height:1.6}
  .ssnote{font-size:var(--t-xs);color:var(--ink-faint)}
  .newmethod{background:var(--card);border:1px solid var(--a);border-left-width:2px;
    border-radius:var(--r-lg);padding:var(--s5) var(--s4);margin-top:var(--s5)}
  .nmlab{font-size:var(--t-cap);font-weight:700;text-transform:uppercase;letter-spacing:.09em;color:var(--a)}
  .newmethod h3{font-family:var(--serif);font-size:var(--t-h2);margin:var(--s1) 0 var(--s2);
    letter-spacing:-.015em;font-weight:600}
  .newmethod p{font-size:var(--t-sm);line-height:1.65;margin:0 0 var(--s3)}
  .nmwhy{font-weight:600;color:var(--ink-soft)}
  .aislot{margin-top:var(--s5);background:none;border:1px dashed var(--line-strong);
    border-radius:var(--r-lg);padding:var(--s4)}
  .aihead{font-size:var(--t-cap);font-weight:700;text-transform:uppercase;letter-spacing:.09em;color:var(--ink-faint)}
  .aislot p{font-size:var(--t-sm);color:var(--ink-soft);line-height:1.6;margin:var(--s2) 0 var(--s3)}

  .diag{display:block;width:100%;text-align:left;margin-top:var(--s3);background:var(--hm-bg);
    border:1px solid var(--hm);border-left-width:2px;border-radius:var(--r-md);
    padding:var(--s3) var(--s4);cursor:pointer;color:var(--hm-ink)}
  .dl{font-size:var(--t-cap);font-weight:700;text-transform:uppercase;letter-spacing:.09em;color:var(--hm)}
  .dt{font-size:var(--t-sm);font-weight:450;margin-top:3px;line-height:1.6}
  .dgo{font-size:var(--t-xs);font-weight:700;color:var(--hm);margin-top:var(--s2)}
  .missnote{font-size:var(--t-xs);color:var(--ink-faint);margin:0 2px var(--s2);line-height:1.55}
  .missrow{display:flex;flex-direction:column;align-items:flex-start;gap:2px;width:100%;
    text-align:left;background:var(--card);border:1px solid var(--line);
    border-left:2px solid var(--hm);border-radius:var(--r-md);padding:var(--s3);
    margin-bottom:var(--s1);cursor:pointer;min-height:48px}
  .missrow:hover{border-color:var(--line-strong);border-left-color:var(--hm)}
  .missrow.due{border-left-color:var(--a)}
  .missrow.due:hover{border-left-color:var(--a)}
  .mn{font-size:var(--t-cap);font-weight:700;text-transform:uppercase;letter-spacing:.09em;color:var(--ink-faint)}
  .mq{font-family:var(--serif);font-size:var(--t-h3);font-weight:500;font-variant-numeric:lining-nums tabular-nums;
    overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%}
  .mwhen{font-size:var(--t-cap);color:var(--ink-faint);margin-top:2px}
  .revban{background:var(--a-tint);border:1px solid var(--a);border-left-width:2px;
    border-radius:var(--r-md);padding:var(--s3);font-size:var(--t-sm);color:var(--ink);
    margin-bottom:var(--s3);line-height:1.6}

  /* sandbox */
  .playtabs{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:var(--s4)}
  .playcard{background:var(--card);border:1px solid var(--line);border-radius:var(--r-lg);
    padding:var(--s4)}
  .playtitle{font-size:var(--t-cap);font-weight:700;text-transform:uppercase;letter-spacing:.09em;
    color:var(--ink-faint)}
  .playeq{font-family:var(--serif);font-size:var(--t-q-sm);font-weight:500;margin:var(--s2) 0 var(--s1);
    font-variant-numeric:lining-nums tabular-nums}
  .playinput{width:100%;margin:var(--s2) 0 var(--s3)}
  .playnote{font-size:var(--t-sm);color:var(--ink-soft);line-height:1.6;margin-top:var(--s3)}
  .playnote.bad{color:var(--hm)}
  .sliderrow{margin-top:var(--s3)}
  .sllab{display:flex;justify-content:space-between;align-items:baseline;
    font-size:var(--t-xs);color:var(--ink-faint);font-weight:600;margin-bottom:3px}
  .sllab b{color:var(--a);font-size:var(--t-sm);font-variant-numeric:lining-nums tabular-nums}
  .slider{width:100%;min-height:36px;accent-color:var(--a);cursor:pointer}
  .playlegend{display:flex;flex-wrap:wrap;gap:var(--s3);font-size:var(--t-xs);
    color:var(--ink-soft);margin-top:var(--s2)}
  .playlegend span{display:flex;align-items:center;gap:5px}
  .swatch{width:14px;height:2px;border-radius:2px;display:inline-block}
  .swatch.curve{background:var(--chalk)}
  .swatch.line{background:var(--a)}
  .ptable{display:flex;gap:3px;margin-top:var(--s3);overflow-x:auto}
  .pcol{flex:1;min-width:44px;text-align:center;background:var(--card-3);
    border:1px solid var(--line);border-radius:var(--r-sm);padding:6px 2px}
  .pcol b{display:block;font-size:var(--t-xs);color:var(--ink-faint);font-weight:700}
  .pcol span{font-family:var(--serif);font-size:var(--t-sm);
    font-variant-numeric:lining-nums tabular-nums}

  .strandrow{margin-bottom:var(--s3)}
  .srtop{display:flex;justify-content:space-between;align-items:baseline;
    font-size:var(--t-sm);font-weight:600;margin-bottom:5px}
  .srn{color:var(--ink-faint);font-weight:450;font-size:var(--t-xs)}
  .settingsrow{display:flex;align-items:center;justify-content:space-between;width:100%;
    background:var(--card);border:1px solid var(--line);border-radius:var(--r-md);
    padding:var(--s4);margin-top:var(--s5);font-size:var(--t-body);font-weight:600;
    cursor:pointer;min-height:50px}
  .settingsrow:hover{border-color:var(--line-strong)}
  .chev{color:var(--ink-faint);font-size:var(--t-h3)}

  .setgroup{background:var(--card);border:1px solid var(--line);border-radius:var(--r-lg);
    padding:var(--s4);margin-bottom:var(--s2)}
  .setlab{font-size:var(--t-cap);font-weight:700;text-transform:uppercase;letter-spacing:.09em;
    color:var(--ink-faint);margin-bottom:var(--s3)}
  .setnote{font-size:var(--t-sm);color:var(--ink-soft);line-height:1.6;margin:0 0 var(--s3)}
  .setwarn{font-size:var(--t-sm);color:var(--no);font-weight:500;margin-top:var(--s2);line-height:1.55}
  .segrow{display:flex;flex-wrap:wrap;gap:5px}
  .seg{background:var(--card);border:1px solid var(--line);border-radius:var(--r-sm);
    padding:9px var(--s3);font-size:var(--t-sm);font-weight:600;cursor:pointer;
    min-height:40px;color:var(--ink-soft)}
  .seg:hover{border-color:var(--line-strong);color:var(--ink)}
  .seg.on{background:var(--a);border-color:var(--a);color:#fff}
  .seg:disabled{opacity:.4;cursor:default}
  .backup{margin-top:var(--s3)}
  .bkarea{width:100%;font-family:var(--mono);font-size:var(--t-cap);line-height:1.5;padding:var(--s3);
    border-radius:var(--r-sm);border:1px solid var(--line);background:var(--card-3);
    color:var(--ink-soft);resize:vertical;margin-bottom:var(--s2)}
  .bkarea:focus{outline:none;border-color:var(--a);color:var(--ink)}

  .scrim{position:fixed;inset:0;background:rgba(20,30,32,.38);z-index:100;animation:fadeIn .18s ease}
  .sheet{position:fixed;left:0;right:0;bottom:0;z-index:101;background:var(--card);
    border-radius:18px 18px 0 0;padding:var(--s2) var(--s4) calc(var(--s5) + env(safe-area-inset-bottom));
    max-width:600px;margin:0 auto;box-shadow:var(--shadow-lift);
    animation:sheetUp .26s cubic-bezier(.22,.8,.3,1)}
  @keyframes sheetUp{from{transform:translateY(100%)}to{transform:none}}
  .grabber{width:34px;height:4px;border-radius:99px;background:var(--line-strong);margin:0 auto var(--s4)}
  .sheet h3{font-family:var(--serif);font-size:var(--t-h3);margin:0 0 var(--s2);letter-spacing:-.01em;font-weight:600}
  .sheet p{font-size:var(--t-sm);color:var(--ink-soft);line-height:1.6;margin:0 0 var(--s3)}
  .toast{position:fixed;left:50%;transform:translateX(-50%);
    bottom:calc(var(--tabh) + var(--s5) + env(safe-area-inset-bottom));z-index:120;
    background:var(--ink);color:var(--paper);border-radius:var(--r-sm);padding:10px var(--s4);
    font-size:var(--t-sm);font-weight:600;box-shadow:var(--shadow);animation:fadeIn .18s ease}

  @media (min-width:780px){
    .app{max-width:940px}
    .tabbar{max-width:940px}
    .grid{grid-template-columns:1fr 1fr 1fr}
  }

  .foot{margin-top:var(--s6);text-align:center;color:var(--ink-faint);font-size:var(--t-xs);line-height:1.6}
  .foot p{max-width:42ch;margin:0 auto}

  /* ==========================================================================
     DARK — the same system, re-inked. An explicit choice in Settings wins over
     the device, which is why it is applied by attribute as well as by query.
     ========================================================================== */
  @media (prefers-color-scheme:dark){
    :root{
      --paper:#0f1516; --card:#171f20; --card-2:#212b2c; --card-3:#141c1d;
      --ink:#e8eeee; --ink-soft:#a0b0b1; --ink-faint:#748688;
      --line:#283334; --line-strong:#3a4849;
      --a:#4cc0b0; --a-tint:#16302e; --a-deep:#5fd0c0;
      --ok:#3cc39c; --ok-bg:#12302a; --ok-ink:#8fe4cd;
      --no:#e8737f; --no-bg:#331b1e; --no-ink:#f6b9bf;
      --hm:#d99b4e; --hm-bg:#2f2415; --hm-ink:#efcf9d;
      --chalk:#a9bcbe;
      --shadow:0 1px 2px rgba(0,0,0,.3), 0 6px 18px rgba(0,0,0,.32);
      --shadow-lift:0 -10px 34px rgba(0,0,0,.5);
    }
    .appbar{background:rgba(15,21,22,.88)}
    .tabbar{background:rgba(15,21,22,.93)}
    .scrim{background:rgba(0,0,0,.58)}
    .sdoor.go,.btn.primary,.seg.on,.lpip.on{color:#08201d}
  }

  .app[data-theme="dark"]{
    --paper:#0f1516; --card:#171f20; --card-2:#212b2c; --card-3:#141c1d;
    --ink:#e8eeee; --ink-soft:#a0b0b1; --ink-faint:#748688;
    --line:#283334; --line-strong:#3a4849;
    --a:#4cc0b0; --a-tint:#16302e; --a-deep:#5fd0c0;
    --ok:#3cc39c; --ok-bg:#12302a; --ok-ink:#8fe4cd;
    --no:#e8737f; --no-bg:#331b1e; --no-ink:#f6b9bf;
    --hm:#d99b4e; --hm-bg:#2f2415; --hm-ink:#efcf9d;
    --chalk:#a9bcbe;
    --shadow:0 1px 2px rgba(0,0,0,.3), 0 6px 18px rgba(0,0,0,.32);
    --shadow-lift:0 -10px 34px rgba(0,0,0,.5);
    background:var(--paper);color:var(--ink);
  }
  .app[data-theme="dark"] .appbar{background:rgba(15,21,22,.88)}
  .app[data-theme="dark"] .tabbar{background:rgba(15,21,22,.93)}
  .app[data-theme="dark"] .sdoor.go,
  .app[data-theme="dark"] .btn.primary,
  .app[data-theme="dark"] .seg.on,
  .app[data-theme="dark"] .lpip.on{color:#08201d}

  .app[data-theme="light"]{
    --paper:#f3f5f5; --card:#ffffff; --card-2:#eaeeee; --card-3:#f7f9f9;
    --ink:#172123; --ink-soft:#5a6b6e; --ink-faint:#8d9ea1;
    --line:#dfe5e5; --line-strong:#c9d3d3;
    --a:#0e6f66; --a-tint:#e1efed; --a-deep:#0a5850;
    --ok:#0f7a63; --ok-bg:#e4f2ee; --ok-ink:#0a5343;
    --no:#b3323d; --no-bg:#fbeaeb; --no-ink:#8a2530;
    --hm:#96590a; --hm-bg:#fbf1de; --hm-ink:#6f4207;
    --chalk:#46595c;
    --shadow:0 1px 2px rgba(23,33,35,.05), 0 6px 18px rgba(23,33,35,.06);
    --shadow-lift:0 -10px 34px rgba(23,33,35,.16);
    background:var(--paper);color:var(--ink);
  }
  .app[data-theme="light"] .appbar{background:rgba(243,245,245,.88)}
  .app[data-theme="light"] .tabbar{background:rgba(243,245,245,.93)}
  .app[data-theme="light"] .sdoor.go,
  .app[data-theme="light"] .btn.primary,
  .app[data-theme="light"] .seg.on,
  .app[data-theme="light"] .lpip.on{color:#fff}
`;

/* =========================================================================
   SLATE — the app.

   The order of a lesson here is deliberate and it is the reverse of the usual
   one: you meet the question first, have a go, and the explanation arrives
   afterwards, attached to what you just did. Nothing is explained at you
   before you have any reason to care.
   ========================================================================= */

const STORE = "mathema.v1";
/* The key the app used under its previous name. A rename must never cost
   anyone their record, so the old one is read once and carried across. */
const STORE_BEFORE = "slate.v1";

function loadState() {
  if (typeof localStorage === "undefined") return {};
  try {
    const now = localStorage.getItem(STORE);
    if (now) return JSON.parse(now) || {};
    const before = localStorage.getItem(STORE_BEFORE);
    return before ? (JSON.parse(before) || {}) : {};
  } catch (e) { return {}; }
}
function saveState(s) {
  if (typeof localStorage === "undefined") return;
  try { localStorage.setItem(STORE, JSON.stringify(s)); } catch (e) { }
}
/* ===========================================================================
   CLOUD SYNC

   Optional, and additive. Mathema works exactly as before with no account and
   no network: saveState writes to localStorage first and that stays the source
   of truth on the device. Signing in adds a copy in Supabase so a record
   follows you to another device.

   The same account as Study It, Lectern and CodeQuest — one sign-in, four apps.

   Two rules, the same as Lectern's, for the same reason:

   Nothing is ever silently overwritten. If a device and the cloud both hold
   real work and they disagree, the learner is asked which to keep. There is no
   merge, because a wrong merge loses work while looking like it worked.

   A sync that did not happen never reports that it did.
   =========================================================================== */
const CLOUD_TABLE = "mathema_state";

let _sbCloud = null;
function cloudClient() {
  if (_sbCloud) return _sbCloud;
  _sbCloud = (async function () {
    try {
      const mod = await import(/* @vite-ignore */ "https://esm.sh/@supabase/supabase-js@2");
      return mod.createClient(
        "https://nfbzmxuruxqgbeeypsoq.supabase.co",
        "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im5mYnpteHVydXhxZ2JlZXlwc29xIiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzk5OTQ0MTUsImV4cCI6MjA5NTU3MDQxNX0.NqQKeIO3pYOk5rbG4YtJApz1lnss_OZvhWuVkIY79-U",
        { auth: { persistSession: true, autoRefreshToken: true, storageKey: "mathema.sb.auth" } }
      );
    } catch (e) { return null; }
  })();
  return _sbCloud;
}

/* Is there anything here worth protecting? Deliberately conservative: one
   answered question counts, because losing one is still losing something. */
function stateHasWork(st) {
  if (!st || typeof st !== "object") return false;
  // The real shape, from MathemaApp: { skills, misses, workDefault, theme... }.
  // Only `skills` and `misses` are work; the rest are preferences.
  const skills = st.skills && typeof st.skills === "object" ? Object.keys(st.skills).length : 0;
  const misses = Array.isArray(st.misses) ? st.misses.length : 0;
  return skills > 0 || misses > 0;
}

/* Compare on the parts that represent work, not on settings or timestamps —
   a different theme is not a conflict worth interrupting anyone for. */
function sameWork(a, b) {
  try {
    const pick = st => JSON.stringify([(st && st.skills) || null, (st && st.misses) || null]);
    return pick(a) === pick(b);
  } catch (e) { return false; }
}

async function cloudPull(sb, userId) {
  const { data, error } = await sb.from(CLOUD_TABLE).select("data").eq("user_id", userId).maybeSingle();
  if (error) throw error;
  return data && data.data ? data.data : null;
}

async function cloudPush(sb, userId, state) {
  const { error } = await sb.from(CLOUD_TABLE)
    .upsert({ user_id: userId, data: state, updated_at: new Date().toISOString() },
            { onConflict: "user_id" });
  if (error) throw error;
}

/* First contact after signing in. Returns what happened rather than acting
   on its own, so the caller can ask the learner when it genuinely matters. */
async function cloudReconcile(sb, userId, local) {
  let remote;
  try { remote = await cloudPull(sb, userId); }
  catch (e) { return { kind: "error", why: (e && e.message) || "Couldn't reach the cloud." }; }

  if (!stateHasWork(remote)) {
    try { await cloudPush(sb, userId, local); return { kind: "uploaded" }; }
    catch (e) { return { kind: "error", why: (e && e.message) || "Upload failed." }; }
  }
  if (!stateHasWork(local)) return { kind: "downloaded", state: remote };
  if (sameWork(local, remote)) return { kind: "same" };
  return { kind: "conflict", remote: remote };
}

function haptic(ms) {
  try { if (navigator && navigator.vibrate) navigator.vibrate(ms); } catch (e) { }
}

/* ---------------------------------------------------------------------------
   CHALK — the drawing kit the widgets share.
   A slate is worked on, wiped, and worked on again. The strokes are drawn with
   a slight wobble so the working surface reads as something you did rather
   than something the app printed at you.
--------------------------------------------------------------------------- */
function wobble(x1, y1, x2, y2, seed) {
  // A deliberate hand, not a shaky one. The deviation is small enough to read
  // as a drawn line rather than a printed one, and no larger — the working
  // surface should look considered, not sketchy.
  const dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len, ny = dx / len;
  const k = ((Math.sin((seed || 1) * 12.9898) * 43758.5453) % 1 + 1) % 1;
  const amp = Math.min(0.8, len * 0.005) * (k - 0.5) * 2;
  const mx = (x1 + x2) / 2 + nx * amp, my = (y1 + y2) / 2 + ny * amp;
  return `M ${x1} ${y1} Q ${mx} ${my} ${x2} ${y2}`;
}
function Stroke({ x1, y1, x2, y2, seed, cls, width }) {
  return <path d={wobble(x1, y1, x2, y2, seed)} className={cls || "chalk"} strokeWidth={width || 2} fill="none" />;
}

/* ---------------------------------------------------------------------------
   WIDGETS — hands-on surfaces.

   Each one exists because the idea underneath it is genuinely spatial. Where
   the math is symbol-pushing (rearranging, integrating), there is no widget,
   because dragging things around a screen with one legal move is a slideshow
   with extra taps, not exploration.
--------------------------------------------------------------------------- */

function NumberLine({ spec, onPick, picked }) {
  const from = spec.from, to = spec.to, span = to - from || 1;
  const W = 320, H = 96, pad = 16;
  const px = v => pad + ((v - from) / span) * (W - pad * 2);
  const stepEvery = span > 60 ? 20 : span > 24 ? 5 : 1;
  const ticks = [];
  for (let v = Math.ceil(from); v <= to; v++) if (v % stepEvery === 0) ticks.push(v);
  const startX = px(spec.start);
  const here = picked == null ? null : px(picked);
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img"
      aria-label={"A number line from " + from + " to " + to + ", starting at " + spec.start}
      onClick={e => {
        if (!onPick) return;
        const r = e.currentTarget.getBoundingClientRect();
        const v = from + ((e.clientX - r.left) / r.width * W - pad) / (W - pad * 2) * span;
        onPick(Math.round(v));
      }}>
      <Stroke x1={pad} y1={58} x2={W - pad} y2={58} seed={3} width={2.2} />
      {ticks.map(v => (
        <g key={v}>
          <Stroke x1={px(v)} y1={52} x2={px(v)} y2={64} seed={v} width={1.4} />
          <text x={px(v)} y={80} className="clab">{v}</text>
        </g>
      ))}
      <circle cx={startX} cy={58} r={5.5} className="cdot" />
      <text x={startX} y={44} className="clab strong">{spec.start}</text>
      {here != null && (
        <g>
          <path d={`M ${startX} 40 Q ${(startX + here) / 2} ${12} ${here} 40`} className="cjump" fill="none" />
          <circle cx={here} cy={58} r={5.5} className="cdot pick" />
          <text x={here} y={94} className="clab pick">{picked}</text>
        </g>
      )}
    </svg>
  );
}

function AreaModel({ spec, revealed }) {
  if (spec.grid2) {
    const cells = [[spec.a[0], spec.b[0]], [spec.a[1], spec.b[0]], [spec.a[0], spec.b[1]], [spec.a[1], spec.b[1]]];
    const W = 300, H = 190, x0 = 54, y0 = 34, cw = 108, ch = 66;
    return (
      <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img" aria-label="An area model of two brackets multiplied">
        <text x={x0 + cw / 2} y={22} className="clab">{spec.a[0]}</text>
        <text x={x0 + cw + cw / 2} y={22} className="clab">{spec.a[1]}</text>
        <text x={30} y={y0 + ch / 2 + 5} className="clab">{spec.b[0]}</text>
        <text x={30} y={y0 + ch + ch / 2 + 5} className="clab">{spec.b[1]}</text>
        {[0, 1].map(i => [0, 1].map(j => (
          <g key={i + "-" + j}>
            <rect x={x0 + i * cw} y={y0 + j * ch} width={cw} height={ch} className="cbox" />
            {revealed && <text x={x0 + i * cw + cw / 2} y={y0 + j * ch + ch / 2 + 6} className="clab strong">
              {cells[j * 2 + i][0] + "·" + cells[j * 2 + i][1]}
            </text>}
          </g>
        )))}
      </svg>
    );
  }
  const w = Math.min(spec.w || 1, 20), h = Math.min(spec.h || 1, 20);
  const cell = Math.max(9, Math.min(20, Math.floor(260 / Math.max(w, h))));
  const W = 300, H = Math.max(120, h * cell + 46);
  const x0 = (W - w * cell) / 2, y0 = 28;
  const rows = [];
  for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) rows.push([i, j]);
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img"
      aria-label={"A rectangle " + w + " across and " + h + " down"}>
      <text x={x0 + w * cell / 2} y={18} className="clab">{spec.hLabel ? spec.w : w}</text>
      <text x={x0 - 14} y={y0 + h * cell / 2 + 5} className="clab">{spec.hideSide === "h" && !revealed ? "?" : h}</text>
      {rows.map(([i, j]) => (
        <rect key={i + "," + j} x={x0 + i * cell} y={y0 + j * cell} width={cell - 1.5} height={cell - 1.5}
          className={"ccell" + (revealed ? " lit" : "")} style={{ animationDelay: (revealed ? (j * w + i) * 6 : 0) + "ms" }} />
      ))}
      {revealed && <text x={W / 2} y={y0 + h * cell + 24} className="clab strong">{w} × {h} = {w * h} squares</text>}
    </svg>
  );
}

function FractionBar({ spec, onPick, picked }) {
  const parts = Math.min(spec.parts || 1, 24);
  const W = 320, H = 92, x0 = 12, bw = W - 24, bh = 46, y0 = 18;
  const pw = bw / parts;
  const filled = picked != null ? picked : (spec.filled || 0);
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img"
      aria-label={"A bar split into " + parts + " equal parts, " + filled + " of them shaded"}>
      {Array.from({ length: parts }).map((_, i) => (
        <rect key={i} x={x0 + i * pw} y={y0} width={pw - 1.5} height={bh}
          className={"cpart" + (i < filled ? " on" : "") + (spec.add && i >= (spec.filled || 0) && i < (spec.filled || 0) + spec.add ? " add" : "")}
          onClick={onPick ? () => onPick(i + 1) : undefined}
          style={{ cursor: onPick ? "pointer" : "default" }} />
      ))}
      <text x={W / 2} y={y0 + bh + 22} className="clab">{filled} of {parts}</text>
    </svg>
  );
}

function Balance({ spec, state, onMove }) {
  // A real balance: whatever you do to one side, the widget does to the other.
  // You cannot make an illegal move here, because the move is applied to both
  // pans by construction — the rule is enforced by the object, not by a warning.
  const L = state.left, R = state.right;
  const W = 320, H = 150;
  const tilt = 0;
  const pan = (items, cx) => (
    <g>
      <Stroke x1={cx - 46} y1={70} x2={cx + 46} y2={70} seed={cx} width={2.2} />
      {items.x !== 0 && Array.from({ length: Math.min(Math.abs(items.x), 9) }).map((_, i) => (
        <rect key={"x" + i} x={cx - 44 + i * 11} y={48} width={9} height={20} className={"cx" + (items.x < 0 ? " negx" : "")} />
      ))}
      {items.n !== 0 && Array.from({ length: Math.min(Math.abs(items.n), 14) }).map((_, i) => (
        <circle key={"n" + i} cx={cx - 42 + (i % 7) * 12} cy={items.x ? 38 - Math.floor(i / 7) * 11 : 60 - Math.floor(i / 7) * 11}
          r={4} className={"cu" + (items.n < 0 ? " neg" : "")} />
      ))}
      <text x={cx} y={88} className="clab">
        {(items.x ? (items.x === 1 ? "x" : items.x + "x") : "") + (items.x && items.n ? (items.n > 0 ? " + " : " − ") : (items.n < 0 ? "−" : "")) + (items.n ? Math.abs(items.n) : (items.x ? "" : "0"))}
      </text>
    </g>
  );
  return (
    <div>
      <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img"
        aria-label={"A balance holding " + L.x + " x plus " + L.n + " against " + R.x + " x plus " + R.n}>
        <g transform={`rotate(${tilt} 160 70)`}>
          <Stroke x1={64} y1={70} x2={256} y2={70} seed={9} width={2} />
          {pan(L, 96)}{pan(R, 224)}
        </g>
        <Stroke x1={160} y1={70} x2={160} y2={120} seed={5} width={2} />
        <Stroke x1={132} y1={122} x2={188} y2={122} seed={6} width={2.2} />
      </svg>
      <div className="moves">
        {onMove && [-1, 1].map(sgn => {
          const amt = sgn * Math.max(1, Math.abs(L.n) || 1);
          if (!L.n) return null;
          if (Math.sign(-L.n) !== sgn) return null;
          return <button key={sgn} className="mv" onClick={() => onMove({ kind: "add", by: -L.n })}>
            {L.n > 0 ? "Take " + L.n + " off both sides" : "Add " + Math.abs(L.n) + " to both sides"}
          </button>;
        })}
        {onMove && L.x !== 1 && L.n === 0 && L.x !== 0 && (
          <button className="mv" onClick={() => onMove({ kind: "div", by: L.x })}>Divide both sides by {L.x}</button>
        )}
        {onMove && <button className="mv ghost" onClick={() => onMove({ kind: "reset" })}>Start over</button>}
      </div>
    </div>
  );
}

function Grapher({ spec, revealed }) {
  const W = 300, H = 220, cx = W / 2, cy = H / 2, u = 18;
  const X = x => cx + x * u, Y = y => cy - y * u;
  const clip = v => Math.max(-8, Math.min(8, v));
  let path = "";
  if (spec.curve) {
    const pts = [];
    for (let x = -8; x <= 8; x += 0.25) {
      const y = spec.curve.a * x * x + spec.curve.b * x + spec.curve.c;
      if (Math.abs(y) <= 9) pts.push(`${X(x)},${Y(y)}`);
      else pts.push(null);
    }
    path = pts.filter(Boolean).join(" ");
  }
  const lineY = x => spec.line.m * x + spec.line.c;
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img"
      aria-label="A pair of axes with the points and line plotted">
      {Array.from({ length: 17 }).map((_, i) => (
        <g key={i}>
          <line x1={X(i - 8)} y1={0} x2={X(i - 8)} y2={H} className="cgrid" />
          <line x1={0} y1={Y(i - 6)} x2={W} y2={Y(i - 6)} className="cgrid" />
        </g>
      ))}
      <Stroke x1={0} y1={cy} x2={W} y2={cy} seed={2} width={1.8} />
      <Stroke x1={cx} y1={0} x2={cx} y2={H} seed={4} width={1.8} />
      {spec.curve && <polyline points={path} className="ccurve" fill="none" />}
      {revealed && spec.line && (
        <Stroke x1={X(-8)} y1={Y(clip(lineY(-8)))} x2={X(8)} y2={Y(clip(lineY(8)))} seed={7} width={2.4} cls="cline" />
      )}
      {(spec.points || []).map((p, i) => (
        <g key={i}>
          <circle cx={X(p[0])} cy={Y(p[1])} r={4.5} className="cdot pick" />
          <text x={X(p[0]) + 8} y={Y(p[1]) - 7} className="clab">({p[0]}, {p[1]})</text>
        </g>
      ))}
    </svg>
  );
}

function UnitCircle({ spec, revealed }) {
  const W = 240, H = 240, cx = 120, cy = 120, R = 82;
  const a = (spec.deg || 0) * Math.PI / 180;
  const px = cx + R * Math.cos(a), py = cy - R * Math.sin(a);
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img" aria-label={"The unit circle with " + spec.deg + " degrees marked"}>
      <circle cx={cx} cy={cy} r={R} className="ccirc" />
      <Stroke x1={cx - R - 14} y1={cy} x2={cx + R + 14} y2={cy} seed={2} width={1.6} />
      <Stroke x1={cx} y1={cy - R - 14} x2={cx} y2={cy + R + 14} seed={3} width={1.6} />
      <Stroke x1={cx} y1={cy} x2={px} y2={py} seed={8} width={2.4} cls="cline" />
      <circle cx={px} cy={py} r={5} className="cdot pick" />
      {revealed && (
        <g>
          <line x1={px} y1={py} x2={px} y2={cy} className="cdash" />
          <line x1={px} y1={py} x2={cx} y2={py} className="cdash" />
          <text x={px} y={cy + (py < cy ? 18 : -8)} className="clab pick" textAnchor="middle">
            {spec.show === "cos" ? "across" : ""}
          </text>
          <text x={cx + (px < cx ? 26 : -26)} y={py} className="clab pick" textAnchor="middle">
            {spec.show === "sin" ? "up" : ""}
          </text>
        </g>
      )}
      <text x={cx + 26} y={cy - 8} className="clab">{spec.deg}°</text>
    </svg>
  );
}

function Shape({ spec, revealed }) {
  const W = 300, H = 190;
  if (spec.of === "circle") {
    const R = 66;
    return (
      <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img" aria-label={"A circle of radius " + spec.rad}>
        <circle cx={W / 2} cy={H / 2} r={R} className="ccirc" />
        <Stroke x1={W / 2} y1={H / 2} x2={W / 2 + R} y2={H / 2} seed={4} width={2} cls="cline" />
        <circle cx={W / 2} cy={H / 2} r={3} className="cdot" />
        <text x={W / 2 + R / 2} y={H / 2 - 8} className="clab pick">r = {spec.rad}</text>
      </svg>
    );
  }
  if (spec.of === "angles" || spec.of === "line-angle") {
    if (spec.of === "line-angle") {
      return (
        <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img" aria-label={"An angle of " + spec.a + " degrees on a straight line"}>
          <Stroke x1={30} y1={130} x2={270} y2={130} seed={2} width={2.2} />
          <Stroke x1={150} y1={130} x2={150 - 90 * Math.cos(spec.a * Math.PI / 180)} y2={130 - 90 * Math.sin(spec.a * Math.PI / 180)} seed={5} width={2.2} cls="cline" />
          <text x={112} y={118} className="clab pick">{spec.a}°</text>
          <text x={190} y={118} className="clab">?</text>
        </svg>
      );
    }
    return (
      <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img" aria-label={"A triangle with angles " + spec.a + " and " + spec.b + " degrees"}>
        <Stroke x1={45} y1={150} x2={255} y2={150} seed={2} width={2.2} />
        <Stroke x1={45} y1={150} x2={140} y2={38} seed={3} width={2.2} />
        <Stroke x1={255} y1={150} x2={140} y2={38} seed={4} width={2.2} />
        <text x={70} y={138} className="clab pick">{spec.a}°</text>
        <text x={224} y={138} className="clab pick">{spec.b}°</text>
        <text x={140} y={62} className="clab">?</text>
      </svg>
    );
  }
  // rectangle / triangle / right-angled triangle, drawn to scale within reason
  const maxU = Math.max(Number(spec.w) || 1, Number(spec.h) || 1, Number(spec.hyp) || 1);
  const u = Math.min(11, 150 / maxU);
  const w = (Number(spec.w) || 4) * u, h = (Number(spec.h) || 4) * u;
  const x0 = (W - w) / 2, y0 = 150 - h;
  if (spec.of === "rect") {
    return (
      <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img" aria-label={"A rectangle " + spec.w + " by " + spec.h}>
        <rect x={x0} y={y0} width={w} height={h} className={"cbox" + (revealed ? " lit" : "")} />
        <text x={x0 + w / 2} y={168} className="clab">{spec.w}</text>
        <text x={x0 - 14} y={y0 + h / 2 + 4} className="clab">{spec.h}</text>
      </svg>
    );
  }
  if (spec.of === "triangle") {
    return (
      <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img" aria-label={"A triangle with base " + spec.w + " and height " + spec.h}>
        <polygon points={`${x0},150 ${x0 + w},150 ${x0 + w / 2},${y0}`} className="cbox" />
        <line x1={x0 + w / 2} y1={150} x2={x0 + w / 2} y2={y0} className="cdash" />
        <text x={x0 + w / 2} y={168} className="clab">base {spec.w}</text>
        <text x={x0 + w / 2 + 20} y={y0 + h / 2} className="clab">h = {spec.h}</text>
      </svg>
    );
  }
  // right-angled
  const hh = (Number(spec.h) || 4) * u;
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img" aria-label="A right-angled triangle">
      <polygon points={`${x0},150 ${x0 + w},150 ${x0},${150 - hh}`} className="cbox" />
      <rect x={x0 + 1} y={150 - 13} width={12} height={12} className="cbox" />
      <text x={x0 + w / 2} y={168} className="clab">{spec.w}</text>
      <text x={x0 - 16} y={150 - hh / 2} className="clab">{spec.h}</text>
      <text x={x0 + w / 2 + 18} y={150 - hh / 2 - 6} className="clab pick">{spec.hyp}</text>
    </svg>
  );
}

/* Column arithmetic, set out the way it is written on paper.

   The generator has been producing this spec all along and the Widget had no
   case for it, so add and sub at their top tier silently showed nothing. The
   answer row appears only once the question is answered — showing it up front
   would hand over the very thing being asked for. */
function Column({ spec, revealed }) {
  const a = String(spec.a == null ? "" : spec.a);
  const b = String(spec.b == null ? "" : spec.b);
  const ans = String(spec.answer == null ? "" : spec.answer);
  const width = Math.max(a.length, b.length, ans.length) + 1;
  const pad = (t) => t.padStart(width, "\u00a0");
  return (
    <div className="colsum" role="img"
      aria-label={"Column arithmetic: " + a + " " + (spec.op || "+") + " " + b +
        (revealed ? ", answer " + ans : "")}>
      <pre>
        {pad(a)}{"\n"}
        <span className="colop">{spec.op || "+"}</span>{pad(b).slice(1)}{"\n"}
        <span className="colrule">{"\u2500".repeat(width)}</span>{"\n"}
        {revealed ? pad(ans) : pad("?")}
      </pre>
    </div>
  );
}

/* A circle with its radius marked. Same story: the spec was being produced and
   nothing drew it, so the circle questions had no diagram at all. */
function Circle({ spec, revealed }) {
  const r = Number(spec.r) || 1;
  const R = 60, cx = 82, cy = 74;
  return (
    <svg className="circw" viewBox="0 0 164 148" role="img"
      aria-label={"A circle of radius " + r}>
      <circle cx={cx} cy={cy} r={R} fill="var(--a-tint)" stroke="var(--a)" strokeWidth="2.5" />
      <line x1={cx} y1={cy} x2={cx + R} y2={cy} stroke="var(--a)" strokeWidth="2.5" />
      <circle cx={cx} cy={cy} r="3.5" fill="var(--a)" />
      <text x={cx + R / 2} y={cy - 9} textAnchor="middle"
        fontSize="14" fontWeight="700" fill="var(--a)">r = {r}</text>
      {revealed && (
        <text x={cx} y={cy + R + 26} textAnchor="middle"
          fontSize="12.5" fill="var(--ink-faint)">
          diameter {2 * r}
        </text>
      )}
    </svg>
  );
}

function Widget({ spec, revealed, onPick, picked, balanceState, onMove }) {
  if (!spec) return null;
  switch (spec.kind) {
    case "numberline": return <NumberLine spec={spec} onPick={onPick} picked={picked} />;
    case "areamodel": return <AreaModel spec={spec} revealed={revealed} />;
    case "fractionbar": return <FractionBar spec={spec} onPick={onPick} picked={picked} />;
    case "balance": return <Balance spec={spec} state={balanceState} onMove={onMove} />;
    case "grapher": return <Grapher spec={spec} revealed={revealed} />;
    case "unitcircle": return <UnitCircle spec={spec} revealed={revealed} />;
    case "shape": return <Shape spec={spec} revealed={revealed} />;
    case "column": return <Column spec={spec} revealed={revealed} />;
    case "circle": return <Circle spec={spec} revealed={revealed} />;
    default: return null;
  }
}

/* ---------------------------------------------------------------------------
   ANSWER BOX
   The live reading underneath is the app showing its working: this is what I
   think you typed. If that reading is wrong, you find out before you commit,
   not after you're marked down for a stray bracket.
--------------------------------------------------------------------------- */
const KEYS = {
  number: ["7", "8", "9", "4", "5", "6", "1", "2", "3", "0", ".", "−"],
  geometry: ["7", "8", "9", "4", "5", "6", "1", "2", "3", "0", "π", "√"],
  algebra: ["x", "(", ")", "^", "/", "+", "−", "×", "2", "3", "√", "="],
  calculus: ["x", "(", ")", "^", "/", "+", "−", "×", "sin", "cos", "ln", "π"]
};
function keypadFor(strand) {
  if (strand === "Calculus" || strand === "Trig") return KEYS.calculus;
  if (strand === "Geometry") return KEYS.geometry;
  if (strand === "Number" || strand === "Fractions" || strand === "Statistics" || strand === "Word problems") return KEYS.number;
  return KEYS.algebra;
}

function AnswerBox({ value, onChange, onSubmit, strand, disabled, placeholder }) {
  const ref = React.useRef(null);
  const reading = React.useMemo(() => {
    const v = String(value || "").trim();
    if (!v) return null;
    const p = S.tryParse(v);
    if (!p.ok) return { bad: true, text: p.error };
    return { bad: false, text: S.print(p.ast) };
  }, [value]);
  const type = ch => {
    const map = { "−": "-", "×": "*", "√": "sqrt(", "π": "pi" };
    onChange(String(value || "") + (map[ch] != null ? map[ch] : ch));
    haptic(4);
    if (ref.current) ref.current.focus();
  };
  return (
    <div className="ansbox">
      <div className="ansrow">
        <input ref={ref} className="ans" value={value} disabled={disabled}
          inputMode="text" autoComplete="off" autoCorrect="off" spellCheck={false}
          placeholder={placeholder || "your answer"}
          aria-label="Your answer"
          onChange={e => onChange(e.target.value)}
          onKeyDown={e => { if (e.key === "Enter" && !disabled) onSubmit(); }} />
        <button className="del" onClick={() => onChange(String(value || "").slice(0, -1))} disabled={disabled} aria-label="Delete">⌫</button>
      </div>
      {reading && (
        <div className={"reading" + (reading.bad ? " bad" : "")}>
          {reading.bad ? "I can't read that: " + reading.text : "Reading it as  " + reading.text}
        </div>
      )}
      <div className="keys">
        {keypadFor(strand).map(k => (
          <button key={k} className="key" disabled={disabled} onClick={() => type(k)}>{k}</button>
        ))}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------------------
   WORK LINES — off by default.

   Answer-only is a complete path to full credit. This adds location and
   confirmation; it never adds strictness. A messy chain with a right answer is
   still a right answer.
--------------------------------------------------------------------------- */
function WorkLines({ lines, setLines, result, live }) {
  const rowState = i => (result && result.rows.find(r => r.index === i)) || null;
  return (
    <div className="work">
      <div className="worklab">Your working — each line is checked against the one above it</div>
      {lines.map((ln, i) => {
        const st = rowState(i);
        const mark = !live || !st ? "" : st.state === "holds" || st.state === "start" ? "ok"
          : st.state === "breaks" || st.state === "off-problem" || st.state === "shape-change" ? "no"
            : st.state === "gained" || st.state === "lost" ? "warn"
              : st.state === "unreadable" || st.state === "unchecked" ? "hm" : "";
        return (
          <div className="wrow" key={i}>
            <span className={"wmark " + mark}>{mark === "ok" ? "✓" : mark === "no" ? "✗" : mark === "warn" ? "⚠" : mark === "hm" ? "?" : ""}</span>
            <input className="wline" value={ln} placeholder={i === 0 ? "start from the problem" : "next line"}
              aria-label={"Working line " + (i + 1)}
              onChange={e => { const c = lines.slice(); c[i] = e.target.value; setLines(c); }}
              onKeyDown={e => {
                if (e.key === "Enter") { const c = lines.slice(); c.splice(i + 1, 0, ""); setLines(c); }
                if (e.key === "Backspace" && ln === "" && lines.length > 1) {
                  e.preventDefault(); const c = lines.slice(); c.splice(i, 1); setLines(c);
                }
              }} />
          </div>
        );
      })}
      <button className="linkbtn" onClick={() => setLines(lines.concat(""))}>Add a line</button>
      {live && result && result.rows.filter(r2 => r2.state === "gained" || r2.state === "lost").map(r2 => (
        <div className="wnote warn" key={r2.index}>Line {r2.index + 1}: {r2.why}</div>
      ))}
      {live && result && result.firstBreak != null && (
        <div className="wnote">
          Everything down to line {result.firstBreak} still matches. Line {result.firstBreak + 1} is where it stops following.
        </div>
      )}
      {live && result && result.intact && lines.some(l => l.trim()) && (
        <div className="wnote good">Every line so far follows from the one above it.</div>
      )}
    </div>
  );
}

/* ---------------------------------------------------------------------------
   HINTS — structural first, one concrete route last.
--------------------------------------------------------------------------- */
function Hints({ q }) {
  const rungs = React.useMemo(() => S.buildHints(q), [q]);
  const [shown, setShown] = React.useState(0);
  React.useEffect(() => { setShown(0); }, [q]);
  return (
    <div className="hints">
      <button className="hintbtn" disabled={shown >= rungs.length} onClick={() => { setShown(s => s + 1); haptic(5); }}>
        {shown === 0 ? "Stuck? Show a hint" : shown >= rungs.length ? "That's every hint" : "Need more help?"}
      </button>
      {rungs.slice(0, shown).map((r, i) => (
        <div className={"rung" + (r.isAnswer ? " answer" : "")} key={i}>
          <div className="rl">{r.label}</div><div>{r.text}</div>
        </div>
      ))}
    </div>
  );
}

/* ---------------------------------------------------------------------------
   PRACTICE — attempt first, explanation after.
--------------------------------------------------------------------------- */
function balanceFrom(spec) {
  const sum = arr => arr.reduce((a, b) => a + (b.kind === "x" ? 0 : b.n), 0);
  const xs = arr => arr.reduce((a, b) => a + (b.kind === "x" ? b.n : 0), 0);
  return { left: { x: xs(spec.left), n: sum(spec.left) }, right: { x: xs(spec.right), n: sum(spec.right) } };
}

function Practice({ skillId, difficulty, seed, onDone, onExit, workDefault, setWorkDefault, mark, diagnose, onOpenSkill, onLearnThis, isReview , onUseGenerated}) {
  const q = React.useMemo(() => K.build(skillId, seed, difficulty), [skillId, seed, difficulty]);
  const [answer, setAnswer] = React.useState("");
  const [phase, setPhase] = React.useState("attempt");
  const [res, setRes] = React.useState(null);
  const [near, setNear] = React.useState(null);
  const [tries, setTries] = React.useState(0);
  const [showWork, setShowWork] = React.useState(!!workDefault);
  const [lines, setLines] = React.useState([""]);
  const [picked, setPicked] = React.useState(null);
  const [bal, setBal] = React.useState(() => q.widget && q.widget.kind === "balance" ? balanceFrom(q.widget) : null);

  React.useEffect(() => {
    setAnswer(""); setPhase("attempt"); setRes(null); setNear(null); setTries(0);
    setLines([""]); setPicked(null);
    setBal(q.widget && q.widget.kind === "balance" ? balanceFrom(q.widget) : null);
    setShowWork(!!workDefault);
  }, [q, workDefault]);

  const chain = React.useMemo(() => {
    if (!showWork) return null;
    const used = lines.filter(l => l.trim() !== "");
    if (!used.length) return null;
    return S.checkChain(lines, q.anchor ? { anchor: q.anchor } : {});
  }, [lines, showWork, q]);

  const submit = () => {
    if (!answer.trim()) return;
    const r = S.check(q.criterion, answer);
    setRes(r);
    setNear(S.readNearMiss(q.criterion, answer, r));
    setTries(t => t + 1);
    haptic(r.ok ? 12 : 6);
    if (r.ok || tries >= 1) { setPhase("after"); mark(skillId, r.ok, seed, difficulty); }
  };

  const applyMove = mv => {
    if (mv.kind === "reset") { setBal(balanceFrom(q.widget)); setLines([""]); return; }
    setBal(b => {
      const nb = mv.kind === "add"
        ? { left: { x: b.left.x, n: b.left.n + mv.by }, right: { x: b.right.x, n: b.right.n + mv.by } }
        : { left: { x: b.left.x / mv.by, n: b.left.n / mv.by }, right: { x: b.right.x / mv.by, n: b.right.n / mv.by } };
      // A move on the balance IS a line of working. If the learner has the work
      // area open, it writes itself — they did the step, so it's theirs.
      const txt = (nb.left.x ? (nb.left.x === 1 ? "x" : nb.left.x + "x") : "0")
        + (nb.left.n ? (nb.left.n > 0 ? " + " + nb.left.n : " - " + Math.abs(nb.left.n)) : "")
        + " = " + (nb.right.x ? nb.right.x + "x + " : "") + nb.right.n;
      setLines(ls => { const c = ls.filter(l => l.trim() !== ""); c.push(txt); return c.concat(""); });
      if (nb.left.x === 1 && nb.left.n === 0) setAnswer(String(nb.right.n));
      return nb;
    });
  };

  const verdictClass = !res ? "" : res.ok ? "good" : res.verdict === "unsure" ? "hm" : "bad";

  return (
    <div className="screen">
      <button className="back" onClick={onExit}>‹ Back</button>
      {isReview && <div className="revban">This is the exact question you missed before, rebuilt from its seed — same numbers, not a lookalike.</div>}

      <div className="qcard">
        <div className="qskill">{q.strand} · {q.skillName}{q.method ? " · " + q.method : ""}</div>
        <div className="qask">{q.ask}</div>
        {q.widget && (
          <Widget spec={q.widget} revealed={phase === "after"} balanceState={bal} onMove={q.widget.kind === "balance" ? applyMove : null}
            onPick={q.widget.kind === "numberline" || q.widget.kind === "fractionbar"
              ? v => { setPicked(v); if (phase === "attempt") setAnswer(String(v)); } : null}
            picked={picked} />
        )}
      </div>

      {true && (
        <>
          <AnswerBox value={answer} onChange={setAnswer} onSubmit={submit} strand={q.strand}
            placeholder={q.criterion.kind === "setEqual" ? "both answers, separated by a comma" : "your answer"} />

          <div className="worktoggle">
            <label className="tgl">
              <input type="checkbox" checked={showWork} onChange={e => { setShowWork(e.target.checked); setWorkDefault(e.target.checked); }} />
              <span>Show my working</span>
            </label>
            <span className="tglnote">Optional. Answering straight out is worth exactly the same.</span>
          </div>

          {showWork && <WorkLines lines={lines} setLines={setLines} result={chain} live={true} />}

          <button className="btn primary" onClick={submit} disabled={!answer.trim()}>Check it</button>
          {res && !res.ok && phase === "attempt" && (
            <div role="status" aria-live="polite" className={"verdict " + verdictClass}>
              {res.verdict === "unsure"
                ? "I couldn't check that one safely, so I'm not going to call it wrong. Try writing it another way."
                : res.verdict === "unreadable" ? "I couldn't read that — " + res.why
                  : res.verdict === "wrong-shape" ? res.why
                    : res.verdict === "too-few" || res.verdict === "too-many" ? res.why
                      : "Not this time."}
              {near && <div className="nearmiss">{near.say}</div>}
              <div className="vsub">Have another go.</div>
            </div>
          )}
          <Hints q={q} />
        </>
      )}

      {phase === "after" && (
        <>
          <div role="status" aria-live="polite" className={"verdict " + verdictClass}>
            {res.ok ? "Correct." : "Not this one."}
            {near && <div className="nearmiss">{near.say}</div>}
            {res.ok && tries > 1 && <div className="vsub">Got there on attempt {tries}.</div>}
          </div>

          {showWork && chain && chain.rows.some(r => r.state !== "blank") && (
            <div className="workback">
              {chain.firstBreak == null
                ? "Every line of your working followed from the one above it."
                : "Your working held together until line " + (chain.firstBreak + 1) + "."}
            </div>
          )}

          {!res.ok && diagnose && (() => {
            const weak = diagnose(skillId);
            if (!weak) return null;
            return (
              <button className="diag" onClick={() => onOpenSkill(weak.id)}>
                <div className="dl">Where this might be coming from</div>
                <div className="dt">{q.skillName} leans on {weak.name}, and {weak.why}</div>
                <div className="dgo">Go to {weak.name} ‹‹</div>
              </button>
            );
          })()}

          <div className="sidebyside">
            <div>
              <div className="teach">
                <div className="teachlab">The idea behind it</div>
                <p>{q.teach}</p>
              </div>
              <Definitions defs={q.defs} />
            </div>
            <WorkedExample worked={q.worked} label="A worked example of this method" />
          </div>

          <div className="steps">
            <div className="teachlab">One way through — not the only one</div>
            {q.steps.map((s, i) => <Step key={i} n={i + 1} st={s} />)}
          </div>

          <button className="btn primary" onClick={onDone}>Next question</button>
          {!res.ok && onLearnThis && (
            <button className="btn" onClick={() => onLearnThis(skillId, q.levelIndex)}>
              Teach me {q.method ? "“" + q.method + "”" : "this"} from the start
            </button>
          )}
          <GeneratedPractice skillId={skillId} difficulty={difficulty} onUse={onUseGenerated} />
          <button className="linkbtn" onClick={onExit}>Back to the map</button>
        </>
      )}
    </div>
  );
}

/* More practice on this skill, from somewhere other than the hand-written
   generator.

   Three things this panel is careful about:

   It only appears where it can work. The gate reads specific question shapes;
   about eight skills produce prompts it cannot read at all. The button is
   hidden there rather than offered and then failing.

   It never shows an unverified question. Whatever appears has been solved
   independently by the app and confirmed by a second route. If nothing
   survives, nothing is shown and the panel says so.

   It says how many were discarded. Seeing "4 asked for, 2 kept" is the
   honest picture of how the pipeline works — discards are not a malfunction,
   they are the check doing its job. */
function GeneratedPractice({ skillId, difficulty, onUse }) {
  const supported = React.useMemo(() => canGenerateFor(K.build, skillId), [skillId]);
  const [state, setState] = React.useState("idle");   // idle | working | done | failed
  const [result, setResult] = React.useState(null);

  if (!supported) return null;

  const run = async () => {
    setState("working"); setResult(null);
    // The examples ARE the specification: the extractor reads exact phrasings,
    // so the skill's own questions are what a proposal has to look like.
    const examples = [];
    for (let i = 0; i < 3; i++) {
      try {
        const q = K.build(skillId, Math.floor(Math.random() * 1e9), difficulty);
        if (q && q.ask) examples.push(q.ask);
      } catch (e) { /* a seed that fails is simply not used as an example */ }
    }
    if (!examples.length) { setState("failed"); setResult({ why: "Couldn't build an example to work from." }); return; }
    const r = await generatePractice(examples, 3, { rounds: 2 });
    setResult(r);
    setState(r.ok ? "done" : "failed");
  };

  return (
    <div className="genpanel">
      {state === "idle" && (
        <button className="btn" onClick={run}>More questions like this</button>
      )}
      {state === "working" && <div className="gennote">Writing questions and checking each one…</div>}

      {state === "failed" && (
        <div className="genfail">
          <div className="gentitle">No new questions this time</div>
          <div className="genwhy">{(result && result.why) || "Nothing could be checked."}</div>
          <div className="genwhy">Nothing unchecked is ever shown, so none are being offered.</div>
          <button className="linkbtn" onClick={run}>Try again</button>
        </div>
      )}

      {state === "done" && result && (
        <div className="genlist">
          <div className="gentitle">
            {result.kept.length} question{result.kept.length === 1 ? "" : "s"}, each solved and confirmed independently
          </div>
          {result.dropped.length > 0 && (
            <div className="genwhy">
              {result.dropped.length} more {result.dropped.length === 1 ? "was" : "were"} discarded for failing that check.
            </div>
          )}
          {result.kept.map((q, i) => (
            <button className="genitem" key={i} onClick={() => onUse && onUse(q)}>
              <span className="genask">{q.ask}</span>
              <span className="genconf">checked by {q.confirmedBy}</span>
            </button>
          ))}
          <button className="linkbtn" onClick={run}>More</button>
        </div>
      )}
    </div>
  );
}


/* ---------------------------------------------------------------------------
   LEARN MODE — taught first, then guided, then let go.

   The practice screen deliberately puts the question before the explanation.
   This is the other route, for when you have never met the idea at all and
   being handed a cold question is just being stuck. It goes:

     read the idea  →  watch one worked through  →  do one with the steps
     still on screen  →  practice on your own

   Both routes exist because both are real. Which one is right depends on
   whether you have anything to attempt with yet.
--------------------------------------------------------------------------- */


/* One renderer for a worked step, used everywhere steps are shown, so the
   written working can never appear in one place and be missing from another. */
function Step({ n, st }) {
  return (
    <div className="stp">
      <span className="sn">{n}</span>
      <div className="stpbody">
        <div>{st.say}</div>
        {st.paper && <pre className="paper inline" aria-label="the working so far">{st.paper.join("\n")}</pre>}
      </div>
    </div>
  );
}

/* The words a method leans on, defined plainly. Teaching that uses "denominator"
   without saying what it means only teaches the people who already knew. */
function Definitions({ defs }) {
  if (!defs || !defs.length) return null;
  return (
    <div className="defs">
      <div className="teachlab">Words used here</div>
      <dl>
        {defs.map((d, i) => (
          <div className="defrow" key={i}>
            <dt>{d[0]}</dt><dd>{d[1]}</dd>
          </div>
        ))}
      </dl>
    </div>
  );
}

/* A worked example with the reason attached to every line. The reasons are the
   point: a learner can follow arithmetic they could not have produced, and
   without the "why" they are no better placed to start the next question. */
function WorkedExample({ worked, label }) {
  if (!worked) return null;
  return (
    <div className="worked">
      <div className="teachlab">{label || "A worked example"} — {worked.title}</div>
      {worked.lines.map((l, i) => (
        <div className="wline-ex" key={i}>
          <span className="wn">{i + 1}</span>
          <div className="wbody">
            <div className="wdoes">{l.does}</div>
            <div className="wwhy">{l.why}</div>
          </div>
          {/* what the page would actually look like at this point, so the
              reasoning and the written working sit side by side */}
          {l.paper && <pre className="paper" aria-label="the working so far">{l.paper.join("\n")}</pre>}
        </div>
      ))}
    </div>
  );
}

function Learn({ skillId, level, onPractise, onExit, onLevel }) {
  const sk = K.BY_ID[skillId];
  const levels = K.levelsOf(skillId) || [];
  const lv = levels[level] || levels[0];
  const [stage, setStage] = React.useState("read");
  const [shown, setShown] = React.useState(0);
  const [answer, setAnswer] = React.useState("");
  const [res, setRes] = React.useState(null);

  // A worked example and a guided one, both real questions at this tier.
  const dFor = level + 1;
  const worked = React.useMemo(() => K.build(skillId, 4242 + level * 7, dFor), [skillId, level, dFor]);
  const guided = React.useMemo(() => K.build(skillId, 9931 + level * 13, dFor), [skillId, level, dFor]);

  React.useEffect(() => { setStage("read"); setShown(0); setAnswer(""); setRes(null); }, [skillId, level]);

  const check = () => {
    const r = S.check(guided.criterion, answer);
    setRes(r);
    haptic(r.ok ? 12 : 6);
  };

  return (
    <div className="screen">
      <button className="back" onClick={onExit}>‹ Back</button>

      <div className="lhead">
        <div className="lskill">{sk.strand} · {sk.name}</div>
        <h2>{lv.method}</h2>
        {levels.length > 1 && (
          <div className="lsteps">
            {levels.map((l2, i) => (
              <button key={i} className={"lpip" + (i === level ? " on" : "")} onClick={() => onLevel(i)}>
                {i + 1}. {l2.method}
              </button>
            ))}
          </div>
        )}
      </div>

      {lv.why && level > 0 && (
        <div className="lwhy"><span>Why a new method here</span>{lv.why}</div>
      )}

      <div className="sidebyside">
        <div>
          <div className="teach"><div className="teachlab">The idea</div><p>{lv.teach}</p></div>
          <Definitions defs={K.defsFor(skillId, level)} />
        </div>
        <WorkedExample worked={K.workedFor(skillId, level)} />
      </div>

      {stage === "read" && (
        <button className="btn primary" onClick={() => setStage("watch")}>Show me one worked through</button>
      )}

      {stage !== "read" && (
        <div className="steps">
          <div className="teachlab">Worked through — {worked.ask}</div>
          {worked.steps.slice(0, stage === "watch" ? shown : worked.steps.length).map((st, i) => (
            <Step key={i} n={i + 1} st={st} />
          ))}
          {stage === "watch" && shown < worked.steps.length && (
            <button className="btn" onClick={() => setShown(v => v + 1)}>
              {shown === 0 ? "Start" : "Next step"}
            </button>
          )}
          {stage === "watch" && shown >= worked.steps.length && (
            <button className="btn primary" onClick={() => setStage("guided")}>Now let me try one</button>
          )}
        </div>
      )}

      {stage === "guided" && (
        <div className="guided">
          <div className="teachlab">Your turn — the steps above stay on screen</div>
          <div className="qask">{guided.ask}</div>
          {guided.widget && <Widget spec={guided.widget} revealed={!!(res && res.ok)}
            balanceState={guided.widget.kind === "balance" ? balanceFrom(guided.widget) : null} />}
          <AnswerBox value={answer} onChange={setAnswer} onSubmit={check} strand={guided.strand} />
          <button className="btn primary" onClick={check} disabled={!answer.trim()}>Check it</button>
          {res && (
            <div role="status" aria-live="polite" className={"verdict " + (res.ok ? "good" : res.verdict === "unsure" ? "hm" : "bad")}>
              {res.ok ? "That's it — same method, your own working." : "Not quite. The steps above are for a different question, but the method is the same one."}
            </div>
          )}
          {res && res.ok && (
            <>
              {level + 1 < levels.length
                ? <button className="btn" onClick={() => onLevel(level + 1)}>Next method: {levels[level + 1].method}</button>
                : null}
              <button className="btn primary" onClick={() => onPractise(dFor)}>Practice this on my own</button>
            </>
          )}
        </div>
      )}
    </div>
  );
}


/* ---------------------------------------------------------------------------
   PRACTICE SESSIONS

   A run of questions rather than one at a time, and it escalates: three right
   in a row moves you up a tier, and when that tier is a genuinely different
   method the session stops and teaches it before continuing. Escalating into
   an unfamiliar method without a word would be setting someone up to fail.

   Two wrong at a tier steps back down. Nothing here is scored or timed; the
   only thing being tracked is whether the method is holding.
--------------------------------------------------------------------------- */
function sessionPool(scope) {
  if (scope === "mixed") return K.SKILLS.map(s2 => s2.id);
  return K.SKILLS.filter(s2 => s2.strand === scope).map(s2 => s2.id);
}

function Session({ scope, startDifficulty, skillIds, onExit, mark, aiMaker }) {
  const pool = React.useMemo(() => (skillIds && skillIds.length ? skillIds : sessionPool(scope)), [scope, skillIds]);
  const [n, setN] = React.useState(0);
  const [d, setD] = React.useState(startDifficulty || 1);
  const [streak, setStreak] = React.useState(0);
  const [misses, setMisses] = React.useState(0);
  const [right, setRight] = React.useState(0);
  const [seed, setSeed] = React.useState(() => (Date.now() % 90000) + 1);
  const [answer, setAnswer] = React.useState("");
  const [res, setRes] = React.useState(null);
  const [announce, setAnnounce] = React.useState(null);   // a new method to teach before continuing

  const skillId = pool[(seed + n) % pool.length];
  const q = React.useMemo(() => K.build(skillId, seed + n * 977, d), [skillId, seed, n, d]);

  const total = 10;
  const done = n >= total;

  const submit = () => {
    if (!answer.trim()) return;
    const r = S.check(q.criterion, answer);
    setRes(r);
    haptic(r.ok ? 12 : 6);
    mark(skillId, r.ok, q.seed, d);
    if (r.ok) { setRight(v => v + 1); setStreak(v => v + 1); setMisses(0); }
    else { setStreak(0); setMisses(v => v + 1); }
  };

  const advance = () => {
    let nd = d;
    if (streak >= 3 && d < 3) nd = d + 1;
    if (misses >= 2 && d > 1) { nd = d - 1; setMisses(0); }
    if (nd !== d) {
      setStreak(0);
      // Only announce when the tier actually introduces a different method.
      const before = K.build(skillId, 1, d), after = K.build(skillId, 1, nd);
      if (nd > d && after.method && after.method !== before.method) {
        setAnnounce({ skillId, from: before.method, to: after.method, why: after.methodWhy, teach: after.teach });
      }
      setD(nd);
    }
    setAnswer(""); setRes(null); setN(v => v + 1);
  };

  if (announce) {
    return (
      <div className="screen">
        <div className="newmethod">
          <div className="nmlab">Three in a row — time for a different method</div>
          <h3>{announce.to}</h3>
          {announce.why && <p className="nmwhy">{announce.why}</p>}
          <p>{announce.teach}</p>
          <button className="btn primary" onClick={() => setAnnounce(null)}>Try one</button>
        </div>
      </div>
    );
  }

  if (done) {
    return (
      <div className="screen">
        <div className="sessend">
          <h2>{right} of {total}</h2>
          <p>You finished at {d === 1 ? "the first" : d === 2 ? "the second" : "the third"} tier
            {q.method ? " — " + q.method.toLowerCase() : ""}.</p>
          <p className="ssnote">Anything you missed is waiting on the map, rebuilt exactly as it was.</p>
          <button className="btn primary" onClick={onExit}>Done</button>
        </div>
      </div>
    );
  }

  return (
    <div className="screen">
      <button className="back" onClick={onExit}>‹ End session</button>
      <div className="sessbar">
        <span>{n + 1} of {total}</span>
        <span className="sstier">Tier {d}{q.method ? " · " + q.method : ""}</span>
      </div>
      <div className="sessdots">
        {Array.from({ length: total }).map((_, i) => <i key={i} className={i < n ? "on" : ""} />)}
      </div>

      <div className="qcard">
        <div className="qskill">{q.strand} · {q.skillName}</div>
        <div className="qask">{q.ask}</div>
        {q.widget && <Widget spec={q.widget} revealed={!!res}
          balanceState={q.widget.kind === "balance" ? balanceFrom(q.widget) : null} />}
      </div>

      {!res && (
        <>
          <AnswerBox value={answer} onChange={setAnswer} onSubmit={submit} strand={q.strand}
            placeholder={q.criterion.kind === "setEqual" ? "both answers, separated by a comma" : "your answer"} />
          <button className="btn primary" onClick={submit} disabled={!answer.trim()}>Check it</button>
        </>
      )}
      {res && (
        <>
          <div role="status" aria-live="polite" className={"verdict " + (res.ok ? "good" : res.verdict === "unsure" ? "hm" : "bad")}>
            {res.ok ? "Correct." : "Not this one."}
            {(() => { const nm = S.readNearMiss(q.criterion, answer, res); return nm ? <div className="nearmiss">{nm.say}</div> : null; })()}
          </div>
          {!res.ok && (
            <div className="steps">
              <div className="teachlab">One way through</div>
              {q.steps.map((st, i) => <Step key={i} n={i + 1} st={st} />)}
            </div>
          )}
          <button className="btn primary" onClick={advance}>{n + 1 >= total ? "Finish" : "Next"}</button>
        </>
      )}
    </div>
  );
}

/* The practice front door: pick what to practice. The AI option is shown but
   plainly switched off, because there is no connection behind it yet and a
   button that quietly did something else would be a lie about what it is. */
function PracticeHome({ onStart, onExit, aiAvailable, onCheck }) {
  return (
    <div className="screen">
      <button className="back" onClick={onExit}>‹ Back</button>
      <div className="hero">
        <h1>Practice</h1>
        <p>Ten questions. Three right in a row moves you up a tier, and if that tier uses a different method it gets taught before you meet it.</p>
      </div>
      <button className="cont" onClick={() => onStart("mixed")}>
        <div className="ct1">Everything</div>
        <div className="ct2">Mixed practice</div>
        <div className="ct3">Questions from every strand you've started.</div>
      </button>

      <button className="cont alt" onClick={onCheck}>
        <div className="ct1">Bring your own</div>
        <div className="ct2">Check my working</div>
        <div className="ct3">Type your own problem and each line of your working gets checked against the one above it.</div>
      </button>

      <div className="secttl">By strand</div>
      <div className="grid">
        {K.strands().map(str => (
          <button key={str} className="skill" onClick={() => onStart(str)}>
            <div className="sname">{str}</div>
            <div className="smeta">{K.SKILLS.filter(s2 => s2.strand === str).length} skills</div>
          </button>
        ))}
      </div>
      <div className="aislot">
        <div className="aihead">Practice written for you</div>
        <p>{aiAvailable
          ? "Connected. Questions can be written to order and checked by the same engine as everything else."
          : "Not connected yet. When it is, questions written to order will still be checked by the same engine as everything else — nothing will be marked by a language model."}</p>
        <button className="btn" disabled={!aiAvailable}>{aiAvailable ? "Write me a set" : "Not connected"}</button>
      </div>
    </div>
  );
}


/* ---------------------------------------------------------------------------
   APP CHROME — routing, tabs, sheets, toasts.

   The thing that most made this feel like a web page rather than an app was
   the Back button: it left the app entirely, because every screen was a piece
   of component state with no history behind it. Routing through the hash fixes
   that — Back now goes back a screen, on a phone and in a browser alike, and
   any screen can be linked to or reloaded into.
--------------------------------------------------------------------------- */
const TABS = [
  { id: "learn", label: "Learn", path: "#/", icon: "M4 5h16M4 12h11M4 19h14" },
  { id: "play", label: "Mess with", path: "#/play", icon: "M6 18L18 6M8 6h10v10" },
  { id: "practice", label: "Practice", path: "#/practice", icon: "M12 4v16M4 12h16" },
  { id: "progress", label: "Progress", path: "#/progress", icon: "M5 19V10M12 19V5M19 19v-6" }
];

/* Mathema keeps its own routes in the URL, and when it runs inside the hub the
   hub is reading that same hash. Without a prefix the two routers fight: the
   hub sees "#/progress", doesn't recognize it, and bounces back to the hub —
   so every internal link in Mathema took you home.

   ROUTE_BASE is that prefix. Empty when Mathema runs standalone, "math" when
   it is mounted behind the hub, and every route it writes and reads goes
   through it. */
let ROUTE_BASE = "";
function setRouteBase(b) { ROUTE_BASE = String(b || "").replace(/^#?\/*/, "").replace(/\/+$/, ""); }
function withBase(path) {
  const clean = String(path || "").replace(/^#\/?/, "");
  return ROUTE_BASE ? "#/" + ROUTE_BASE + (clean ? "/" + clean : "") : "#/" + clean;
}

function parseRoute(hash) {
  let raw = String(hash || "").replace(/^#\/?/, "");
  if (ROUTE_BASE) {
    // Only routes under our own prefix belong to us. Anything else is the
    // hub's business and is treated as our home screen.
    if (raw === ROUTE_BASE) raw = "";
    else if (raw.indexOf(ROUTE_BASE + "/") === 0) raw = raw.slice(ROUTE_BASE.length + 1);
    else raw = "";
  }
  const seg = raw.split("/").filter(Boolean).map(decodeURIComponent);
  if (!seg.length) return { name: "map", tab: "learn", depth: 0 };
  switch (seg[0]) {
    case "practice": return { name: "practice", tab: "practice", depth: 0 };
    case "check": return { name: "check", tab: "practice", depth: 1 };
    case "play": return { name: "play", tab: "play", depth: 0, which: seg[1] || "rect" };
    case "settings": return { name: "settings", tab: "progress", depth: 1 };
    case "progress": return { name: "progress", tab: "progress", depth: 0 };
    case "placement": return { name: "placement", tab: "progress", depth: 1 };
    case "session": return { name: "session", tab: "practice", depth: 1, scope: seg[1] || "mixed" };
    case "learn": return { name: "learn", tab: "learn", depth: 1, skillId: seg[1], level: Number(seg[2] || 0) };
    case "skill": return { name: "skill", tab: "learn", depth: 1, skillId: seg[1] };
    case "review": return { name: "skill", tab: "progress", depth: 1, skillId: seg[1], seed: Number(seg[2]), difficulty: Number(seg[3]), review: true };
    default: return { name: "map", tab: "learn", depth: 0 };
  }
}

/* The mark: squares turning as they shrink, with a spiral traced through one
   corner of each. The spiral is produced by the squares rather than drawn on
   top of them, which is the mathematical idea the icon is standing for.

   The color runs from cyan to pink across the sequence. This is the app-bar
   version: fewer squares than the full icon, because at 17px any more turns to
   mush. Generated from the same geometry as mathema-icon.svg. */
function Mark({ size }) {
  const s2 = size || 22;
  return (
    <svg viewBox="0 0 24 24" width={s2} height={s2} aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: MARK_PATHS }} />
  );
}
const MARK_PATHS = "<polygon points=\"20.60,20.60 3.40,20.60 3.40,3.40 20.60,3.40\" fill=\"none\" stroke=\"#22d3ee\" stroke-width=\"1.25\" opacity=\"0.55\" stroke-linejoin=\"round\"/><polygon points=\"17.70,20.77 3.23,17.70 6.30,3.23 20.77,6.30\" fill=\"none\" stroke=\"#45c2e4\" stroke-width=\"1.19\" opacity=\"0.61\" stroke-linejoin=\"round\"/><polygon points=\"15.22,20.40 3.60,15.22 8.78,3.60 20.40,8.78\" fill=\"none\" stroke=\"#68b2db\" stroke-width=\"1.13\" opacity=\"0.67\" stroke-linejoin=\"round\"/><polygon points=\"13.21,19.64 4.36,13.21 10.79,4.36 19.64,10.79\" fill=\"none\" stroke=\"#8ba2d2\" stroke-width=\"1.07\" opacity=\"0.73\" stroke-linejoin=\"round\"/><polygon points=\"11.65,18.64 5.36,11.65 12.35,5.36 18.64,12.35\" fill=\"none\" stroke=\"#ae92c8\" stroke-width=\"1.02\" opacity=\"0.79\" stroke-linejoin=\"round\"/><polygon points=\"10.52,17.53 6.47,10.52 13.48,6.47 17.53,13.48\" fill=\"none\" stroke=\"#d182bf\" stroke-width=\"0.96\" opacity=\"0.85\" stroke-linejoin=\"round\"/><polygon points=\"9.77,16.38 7.62,9.77 14.23,7.62 16.38,14.23\" fill=\"none\" stroke=\"#f472b6\" stroke-width=\"0.90\" opacity=\"0.91\" stroke-linejoin=\"round\"/><polyline points=\"20.60,20.60 17.70,20.77 15.22,20.40 13.21,19.64 11.65,18.64 10.52,17.53 9.77,16.38\" fill=\"none\" stroke=\"#f472b6\" stroke-width=\"1.15\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>";

function Icon({ d, size }) {
  return (
    <svg viewBox="0 0 24 24" width={size || 22} height={size || 22} aria-hidden="true">
      <path d={d} stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" fill="none" />
    </svg>
  );
}

function TabBar({ active, go }) {
  return (
    <nav className="tabbar" role="tablist" aria-label="Sections">
      {TABS.map(t2 => (
        <button key={t2.id} role="tab" aria-selected={active === t2.id}
          className={"tab" + (active === t2.id ? " on" : "")}
          onClick={() => { haptic(4); go(t2.path); }}>
          <Icon d={t2.icon} />
          <span>{t2.label}</span>
        </button>
      ))}
    </nav>
  );
}

/* A sheet, not a browser dialog. window.confirm looks like the page is in
   trouble; a sheet looks like the app asking a question. */
function Sheet({ open, title, body, confirmLabel, danger, onConfirm, onClose }) {
  React.useEffect(() => {
    if (!open || typeof window === "undefined") return;
    const onKey = e => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onClose]);
  if (!open) return null;
  return (
    <>
      <div className="scrim" onClick={onClose} />
      <div className="sheet" role="dialog" aria-modal="true" aria-label={title}>
        <div className="grabber" />
        <h3>{title}</h3>
        <p>{body}</p>
        <button className={"btn " + (danger ? "danger" : "primary")} onClick={onConfirm}>{confirmLabel}</button>
        <button className="btn" onClick={onClose}>Cancel</button>
      </div>
    </>
  );
}

function Toast({ text }) {
  if (!text) return null;
  return <div className="toast" role="status">{text}</div>;
}

/* ---------------------------------------------------------------------------
   PROGRESS — what's actually known, without inventing a score.
--------------------------------------------------------------------------- */
function Progress({ onPlacement, state, onOpenMiss, onOpen, onReset, onSettings }) {
  const strands = K.strands();
  const totals = React.useMemo(() => {
    let seen = 0, right = 0, started = 0, methods = 0, methodsTotal = 0;
    K.SKILLS.forEach(sk => {
      const st = state.skills[sk.id];
      const L = K.levelsOf(sk.id) || [];
      methodsTotal += L.length;
      if (st && st.seen) {
        started++; seen += st.seen; right += st.right;
        // A method counts as met once you've answered at that tier or beyond.
        methods += Math.min(L.length, Math.max(1, st.top || 1));
      }
    });
    return { seen, right, started, methods, methodsTotal };
  }, [state]);

  return (
    <div className="screen">
      <div className="hero"><h1>Progress</h1>
        <p>{totals.seen === 0
          ? "Nothing answered yet. Anything you do gets recorded here, including what you miss."
          : totals.right + " of " + totals.seen + " answered correctly, across " + totals.started + (totals.started === 1 ? " skill" : " skills") + "."}</p>
      </div>

      {/* The placement test. It lives here rather than on the map because it is
          about where you are, not what you are doing next — and it is offered
          rather than pushed: nobody should have to sit a test to start using
          the app. The wording changes once there is progress, because "where
          do I start" and "check I haven't drifted" are different questions. */}
      <button className="cont" onClick={onPlacement}>
        <div>
          <div className="cl">{totals.seen === 0 ? "New here?" : "Not sure what to do next?"}</div>
          <div className="ct2">Find where to start</div>
          <div className="cs">
            About twenty questions, getting harder or easier as you go. It gives you what you're
            ready to learn next, strand by strand — not a year group.
          </div>
        </div>
        <div className="go2">›</div>
      </button>

      {dueSkills(state).length > 0 && (
        <>
          <div className="secttl">Due for review</div>
          <div className="missnote">These come back on a schedule: a day after you first get one, then three, then a week, then three weeks. A miss resets the gap. Ignoring it changes nothing else.</div>
          {dueSkills(state).slice(0, 8).map(d2 => (
            <button className="missrow due" key={d2.sk.id} onClick={() => onOpen(d2.sk.id)}>
              <span className="mn">{d2.sk.strand}</span>
              <span className="mq">{d2.sk.name}</span>
              <span className="mwhen">left {agoLabel(Date.now() - d2.rec.last)}, due after {d2.info.days} {d2.info.days === 1 ? "day" : "days"}</span>
            </button>
          ))}
        </>
      )}

      {(state.misses || []).length > 0 && (
        <>
          <div className="secttl">Questions you missed</div>
          <div className="missnote">Each one rebuilds exactly as it was — same numbers, not a lookalike. Getting it right clears it.</div>
          {(state.misses || []).slice().reverse().map((m2, i) => (
            <button className="missrow" key={m2.skill + "-" + m2.seed + "-" + i} onClick={() => onOpenMiss(m2)}>
              <span className="mn">{(K.BY_ID[m2.skill] || {}).name || m2.skill}</span>
              <span className="mq">{(() => { try { return K.build(m2.skill, m2.seed, m2.difficulty).ask; } catch (e) { return "—"; } })()}</span>
            </button>
          ))}
        </>
      )}

      <div className="secttl">By strand</div>
      {strands.map(str => {
        const inStrand = K.SKILLS.filter(sk => sk.strand === str);
        const touched = inStrand.filter(sk => (state.skills[sk.id] || {}).seen);
        const pct = Math.round(touched.length / inStrand.length * 100);
        return (
          <div className="strandrow" key={str}>
            <div className="srtop"><span>{str}</span><span className="srn">{touched.length} of {inStrand.length}</span></div>
            <div className="sbar"><i style={{ width: pct + "%" }} /></div>
          </div>
        );
      })}

      <button className="settingsrow" onClick={onSettings}>
        <span>Settings, backup and restore</span><span className="chev">›</span>
      </button>

      <div className="foot">
        <p>No points, no streaks, no badges. The only thing tracked is whether the method is holding.</p>
        <button className="linkbtn" onClick={onReset}>Clear everything on this device</button>
      </div>
    </div>
  );
}


/* ---------------------------------------------------------------------------
   REVIEW SCHEDULE

   A memory fades on a schedule, so review works best on one too. The intervals
   here are deliberately plain and stated out loud, because a learner should be
   able to disagree with the plan rather than be steered by a number they can't
   see. Nothing is locked or hidden if you ignore it — a due date is a
   suggestion, not a gate.
--------------------------------------------------------------------------- */
const DAY = 86400000;
const INTERVALS = [1, 3, 7, 21, 60];        // days, by how many times running you've had it right

function dueInfo(rec) {
  if (!rec || !rec.last) return null;
  const run = Math.max(0, Math.min(INTERVALS.length - 1, (rec.run || 0) - 1));
  const wait = INTERVALS[run] * DAY;
  const due = rec.last + wait;
  return { due: due, overdue: Date.now() - due, days: INTERVALS[run] };
}
function dueSkills(state) {
  const out = [];
  K.SKILLS.forEach(sk => {
    const rec = state.skills[sk.id];
    if (!rec || !rec.seen) return;
    const info = dueInfo(rec);
    if (info && info.overdue >= 0) out.push({ sk: sk, info: info, rec: rec });
  });
  return out.sort((a, b) => b.info.overdue - a.info.overdue);
}
function agoLabel(ms) {
  const d = Math.floor(ms / DAY);
  if (d >= 1) return d === 1 ? "a day" : d + " days";
  const h = Math.floor(ms / 3600000);
  if (h >= 1) return h === 1 ? "an hour" : h + " hours";
  return "a few minutes";
}

/* ---------------------------------------------------------------------------
   CHECK MY WORKING

   A different shape of help: bring your own problem. The app does not solve it
   — it checks that each line of your working still follows from the one above,
   which is the part that is actually hard to do for yourself. It says plainly
   that agreeing with your steps is not the same as agreeing with your answer,
   because the first line could be a misreading of the question and every line
   after it would still be consistent.
--------------------------------------------------------------------------- */
function Workbench() {
  const [lines, setLines] = React.useState(["", ""]);
  const result = React.useMemo(() => {
    const used = lines.filter(l => l.trim() !== "");
    if (used.length < 1) return null;
    return S.checkChain(lines, {});
  }, [lines]);

  const rowState = i => (result && result.rows.find(r => r.index === i)) || null;
  const readable = lines.filter(l => l.trim() !== "").length;

  /* Checking that each line follows from the one above says nothing about
     whether the answer is right \u2014 a chain can be flawless and still start from
     a misread question. The solver closes that: it reads the first line, works
     the answer out on its own, and compares. It refuses anything it cannot
     both solve AND confirm, so silence here means "I could not check this",
     never "you are wrong". */
  const answerCheck = React.useMemo(() => {
    const used = lines.filter(l => l.trim() !== "");
    if (used.length < 2 || typeof SOLVER === "undefined") return null;
    const problem = used[0];
    /* A last line of working reads "x = 5", not "5". Handing the whole string
       to the gate made it disagree with a correct answer, which is worse than
       saying nothing: take the right-hand side when the line is of that shape. */
    let last = used[used.length - 1].trim();
    const asAssignment = last.match(/^[a-z]\s*=\s*(.+)$/i);
    if (asAssignment) last = asAssignment[1].trim();
    let readableProblem = null;
    try { readableProblem = SOLVER.extract(problem); } catch (e) { return null; }
    if (!readableProblem) return null;
    let v = null;
    try { v = SOLVER.verify({ ask: problem, answer: last }); } catch (e) { return null; }
    if (v && v.accept) return { state: "matches" };
    if (v && /disagrees/.test(v.why || "")) return { state: "differs", ours: v.ours };
    return null;                       // could not solve or confirm: say nothing
  }, [lines]);

  return (
    <div className="screen">
      <div className="hero">
        <h1>Check my working</h1>
        <p>Your own problem, your own method. Type each line of your working and every one is checked against the line above it — any route that stays true will pass.</p>
      </div>

      <div className="work">
        {lines.map((ln, i) => {
          const st = rowState(i);
          const mark = !st ? "" : st.state === "holds" || st.state === "start" ? "ok"
            : st.state === "breaks" || st.state === "shape-change" ? "no"
              : st.state === "gained" || st.state === "lost" ? "warn"
                : st.state === "unreadable" || st.state === "unchecked" ? "hm" : "";
          return (
            <div className="wrow" key={i}>
              <span className={"wmark " + mark}>{mark === "ok" ? "✓" : mark === "no" ? "✗" : mark === "warn" ? "⚠" : mark === "hm" ? "?" : ""}</span>
              <input className="wline" value={ln} inputMode="text" autoComplete="off" spellCheck={false}
                placeholder={i === 0 ? "the problem, e.g.  3(x + 2) = 18" : "your next line"}
                aria-label={"Line " + (i + 1)}
                onChange={e => { const c = lines.slice(); c[i] = e.target.value; setLines(c); }}
                onKeyDown={e => {
                  if (e.key === "Enter") { const c = lines.slice(); c.splice(i + 1, 0, ""); setLines(c); }
                  if (e.key === "Backspace" && ln === "" && lines.length > 2) { e.preventDefault(); const c = lines.slice(); c.splice(i, 1); setLines(c); }
                }} />
            </div>
          );
        })}
        <button className="linkbtn" onClick={() => setLines(lines.concat(""))}>Add a line</button>
      </div>

      {result && readable >= 2 && (
        <div role="status" aria-live="polite" className={"verdict " + (result.firstBreak != null ? "bad" : result.rows.some(r => r.state === "gained" || r.state === "lost") ? "hm" : "good")}>
          {result.firstBreak != null
            ? "Line " + (result.firstBreak + 1) + " is where it stops following from the line above."
            : "Every line follows from the one above it."}
          {result.rows.filter(r => r.state === "gained" || r.state === "lost").map(r => (
            <div className="nearmiss" key={r.index}>Line {r.index + 1}: {r.why}</div>
          ))}
          {result.rows.filter(r => r.state === "unreadable").map(r => (
            <div className="nearmiss" key={"u" + r.index}>Line {r.index + 1} couldn't be read: {r.why}</div>
          ))}
          {answerCheck && answerCheck.state === "matches" && (
            <div className="nearmiss">Your last line is also the answer I get working it out separately.</div>
          )}
          {answerCheck && answerCheck.state === "differs" && (
            <div className="nearmiss">Working it out separately I get {String(answerCheck.ours)}, so the first line and the last one don't agree \u2014 worth checking you read the problem the way you meant to.</div>
          )}
        </div>
      )}

      <div className="teach">
        <div className="teachlab">What this does and doesn't tell you</div>
        <p>It checks that each line follows from the one before it. It also can't see anything you did in your head between two lines — only whether both are true.</p>
        <p>Where the first line is a problem it can solve on its own, it will also work the answer out separately and say whether your last line agrees. It only says so when it has confirmed its own answer by a second route, so saying nothing means it couldn't check — not that you are wrong.</p>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------------------
   SETTINGS, BACKUP AND RESTORE

   Everything is on this device and nowhere else. There is no account, so a
   cleared browser is a cleared record — which is worth saying plainly rather
   than leaving to be discovered.
--------------------------------------------------------------------------- */
/* Cloud sync panel.

   States the truth about where the record lives: the device holds it, the
   cloud holds a copy. Never claims a sync that did not happen. */
function CloudSync({ state, setState, say }) {
  const [user, setUser] = React.useState(null);
  const [status, setStatus] = React.useState("off");  // off|working|ok|error|conflict
  const [note, setNote] = React.useState(null);
  const [at, setAt] = React.useState(null);
  const [pending, setPending] = React.useState(null); // the cloud copy awaiting a choice
  const [email, setEmail] = React.useState("");
  const [pw, setPw] = React.useState("");
  const [mode, setMode] = React.useState("in");
  const readyRef = React.useRef(false);

  const settle = React.useCallback(async (sb, u) => {
    setStatus("working");
    const r = await cloudReconcile(sb, u.id, state);
    if (r.kind === "error") { setStatus("error"); setNote(r.why); return; }
    if (r.kind === "downloaded") {
      setState(st => Object.assign({}, st, r.state));
      readyRef.current = true; setStatus("ok"); setAt(Date.now());
      say && say("Your saved record was restored.");
      return;
    }
    if (r.kind === "conflict") { setPending(r.remote); setStatus("conflict"); return; }
    readyRef.current = true; setStatus("ok"); setAt(Date.now());
  }, [state, setState, say]);

  // Restore an existing session on load.
  React.useEffect(() => {
    let alive = true;
    (async () => {
      const sb = await cloudClient();
      if (!sb || !alive) return;
      try {
        const { data } = await sb.auth.getSession();
        const u = data && data.session && data.session.user;
        if (u && alive) { setUser(u); settle(sb, u); }
      } catch (e) { }
    })();
    return () => { alive = false; };
  }, []);   // once: a later state change must not re-run the reconcile

  // Debounced upload, only after the first reconcile has settled — a
  // half-loaded device must never stamp on a good cloud copy.
  React.useEffect(() => {
    if (!user || !readyRef.current) return;
    const t = setTimeout(async () => {
      const sb = await cloudClient();
      if (!sb) return;
      setStatus("working");
      try { await cloudPush(sb, user.id, state); setStatus("ok"); setAt(Date.now()); setNote(null); }
      catch (e) { setStatus("error"); setNote((e && e.message) || "Sync failed."); }
    }, 2500);
    return () => clearTimeout(t);
  }, [state, user]);

  const signIn = async () => {
    setNote(null);
    if (!email.trim() || !pw) { setNote("Enter an email and a password."); return; }
    const sb = await cloudClient();
    if (!sb) { setNote("Couldn't reach the sign-in service."); return; }
    setStatus("working");
    const fn = mode === "in" ? "signInWithPassword" : "signUp";
    const { data, error } = await sb.auth[fn]({ email: email.trim(), password: pw });
    if (error) { setStatus("off"); setNote(error.message); return; }
    if (!data.session) { setStatus("off"); setNote("Check your email to confirm the account, then sign in."); return; }
    setUser(data.user); setEmail(""); setPw("");
    settle(sb, data.user);
  };

  const keepCloud = () => {
    setState(st => Object.assign({}, st, pending));
    setPending(null); readyRef.current = true; setStatus("ok"); setAt(Date.now());
    say && say("The cloud copy is now on this device.");
  };
  const keepDevice = async () => {
    const sb = await cloudClient();
    setPending(null); readyRef.current = true;
    if (!sb || !user) return;
    setStatus("working");
    try { await cloudPush(sb, user.id, state); setStatus("ok"); setAt(Date.now());
          say && say("This device's record is now the cloud copy."); }
    catch (e) { setStatus("error"); setNote((e && e.message) || "Sync failed."); }
  };

  const signOut = async () => {
    const sb = await cloudClient();
    readyRef.current = false;
    if (sb) { try { await sb.auth.signOut(); } catch (e) { } }
    setUser(null); setStatus("off"); setAt(null); setNote(null); setPending(null);
  };

  if (status === "conflict" && pending) {
    return (
      <section className="card">
        <h2>Two records</h2>
        <p className="muted">
          This device and your account both have work, and they don't match. Nothing has changed
          yet. Keeping one replaces the other — they can't be merged without risking losing part
          of either.
        </p>
        <div className="row">
          <button className="btn primary" onClick={keepCloud}>Use the saved copy</button>
          <button className="btn" onClick={keepDevice}>Keep this device</button>
        </div>
      </section>
    );
  }

  if (user) {
    const line = status === "working" ? "Syncing…"
      : status === "error" ? ("Not synced — " + (note || "something went wrong"))
        : at ? ("Synced at " + new Date(at).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" }))
          : "Connected.";
    return (
      <section className="card">
        <h2>Cloud sync</h2>
        <p className="muted">Signed in as {user.email}. {line}</p>
        <p className="muted">
          Your record is still saved on this device — the cloud keeps a copy so it follows you to
          another one. The same account works in Study It, Lectern and CodeQuest.
        </p>
        <div className="row"><button className="btn" onClick={signOut}>Sign out of cloud</button></div>
      </section>
    );
  }

  return (
    <section className="card">
      <h2>Cloud sync</h2>
      <p className="muted">
        Off — your record is saved on this device only. Sign in to keep a copy so it follows you
        to another device. The same account works in Study It, Lectern and CodeQuest.
      </p>
      <div className="row">
        <button className={"btn" + (mode === "in" ? " primary" : "")} onClick={() => { setMode("in"); setNote(null); }}>Sign in</button>
        <button className={"btn" + (mode === "up" ? " primary" : "")} onClick={() => { setMode("up"); setNote(null); }}>Create account</button>
      </div>
      <input className="ans cloudin" type="email" autoComplete="email" placeholder="you@example.com"
        value={email} onChange={e => setEmail(e.target.value)} />
      <input className="ans cloudin" type="password" placeholder="Password"
        autoComplete={mode === "in" ? "current-password" : "new-password"}
        value={pw} onChange={e => setPw(e.target.value)}
        onKeyDown={e => { if (e.key === "Enter") signIn(); }} />
      {note && <p className="muted">{note}</p>}
      <div className="row">
        <button className="btn primary" disabled={status === "working"} onClick={signIn}>
          {status === "working" ? "Working…" : mode === "in" ? "Sign in" : "Create account"}
        </button>
      </div>
      <p className="muted">Nothing is uploaded until you sign in, and nothing is ever overwritten without asking you first.</p>
    </section>
  );
}

/* Where to start.

   Twenty questions, adaptive, judged by the same criterion the practice screen
   uses — there is no second way of deciding "correct", because two would be
   one too many.

   What it deliberately does not show: a grade level. The report is a per-strand
   reach and a list of what to try next, because "Year 9" would average away the
   only interesting thing, which is that someone can be fluent at algebra and
   shaky on circle theorems in the same afternoon. */
function Placement({ state, setState, onExit, onOpen }) {
  const [run, setRun] = React.useState(null);      // null = not started
  const [q, setQ] = React.useState(null);
  const [given, setGiven] = React.useState("");
  const [unreadable, setUnreadable] = React.useState(null);
  const [report, setReport] = React.useState(null);

  const askNext = React.useCallback((st) => {
    const sk = nextSkill(st, K.SKILLS, K.BY_ID);
    if (!sk) { setReport(placementReport(st, K.SKILLS, K.BY_ID)); setQ(null); return; }
    // Mid difficulty: the question should test whether the skill is there at
    // all, not whether the hardest tier of it is.
    setQ(K.build(sk.id, Math.floor(Math.random() * 1e9), 2));
    setGiven(""); setUnreadable(null);
  }, []);

  const begin = () => {
    const st = startPlacement(K.SKILLS, K.BY_ID, { maxQuestions: 20 });
    setRun(st); setReport(null); askNext(st);
  };

  const answer = (correct) => {
    const st = recordAnswer(run, q.skill, correct, K.SKILLS, K.BY_ID);
    setRun(st); askNext(st);
  };

  const submit = () => {
    if (!given.trim()) return;
    // S.check is the same judge the practice screen uses. There is deliberately
    // no second marking path here.
    const r = S.check(q.criterion, given);
    // Unreadable is not wrong — it tells us nothing about the skill, so the
    // question is re-asked rather than counted against the learner.
    // S.check reports "unreadable" as a VERDICT, not a boolean flag. Reading it
    // as r.unreadable would always be undefined, and every mistyped answer
    // would have been counted as a wrong one — placing the learner lower than
    // they are on the strength of a typo.
    if (r.verdict === "unreadable") { setUnreadable(r.why || "That couldn't be read."); setGiven(""); return; }
    setUnreadable(null);
    answer(!!r.ok);
  };

  if (!run && !report) {
    return (
      <div className="screen">
        <div className="hero"><h1>Where to start</h1></div>
        <section className="card">
          <p className="muted">
            About twenty questions, getting harder or easier depending on how you do. It won't
            give you a year group — that would average away the useful part. It gives you what
            you're ready to learn next, strand by strand.
          </p>
          <p className="muted">
            Skipping is fine and is not counted against you. Nothing here changes your saved
            progress unless you ask it to at the end.
          </p>
          <div className="row"><button className="btn primary" onClick={begin}>Start</button>
            <button className="btn" onClick={onExit}>Not now</button></div>
        </section>
      </div>
    );
  }

  if (report) {
    const strands = Object.keys(report.reach);
    return (
      <div className="screen">
        <div className="hero"><h1>Where to start</h1></div>
        <section className="card">
          <h2>What you can already do</h2>
          {strands.length === 0
            ? <p className="muted">Not enough went right to say yet — that's fine, and the list below is where to begin.</p>
            : strands.map(st => (
              <p className="muted" key={st}><b>{st}</b> — as far as {report.reach[st].name}</p>
            ))}
        </section>

        <section className="card">
          <h2>Ready to try next</h2>
          {report.frontier.length === 0
            ? <p className="muted">Nothing is clearly next from this run.</p>
            : report.frontier.slice(0, 8).map(id => (
              <button className="cont" key={id} onClick={() => onOpen && onOpen(id)}>
                <div>
                  <div className="ct2">{K.BY_ID[id].name}</div>
                  <div className="cs">
                    {K.BY_ID[id].strand}
                    {report.frontierEvidence[id] === "inferred" ? " · not tested, but everything it needs is there" : " · you tried this one"}
                  </div>
                </div>
                <div className="go2">›</div>
              </button>
            ))}
        </section>

        <section className="card">
          <p className="muted">{report.caveat}</p>
          <p className="muted">
            Answered {report.asked}, which settled {report.secure.length + report.shaky.length} skills
            between them — the rest follows from what depends on what.
          </p>
          <div className="row"><button className="btn" onClick={onExit}>Done</button></div>
        </section>
      </div>
    );
  }

  return (
    <div className="screen">
      <div className="hero">
        <h1>Where to start</h1>
        <div className="obsub">Question {run.asked.length + 1} of about 20</div>
      </div>
      <section className="card">
        <div className="muted" style={{ marginBottom: 6 }}>{K.BY_ID[q.skill].strand}</div>
        <p className="ask">{q.ask}</p>
        <input className="ans" value={given} placeholder="Your answer"
          aria-label={"Your answer to: " + (q && q.ask ? q.ask : "this question")}
          onChange={e => setGiven(e.target.value)}
          onKeyDown={e => { if (e.key === "Enter") submit(); }} />
        {unreadable && <div className="fb no" style={{ marginTop: 10 }}>{unreadable} Nothing was counted — try writing it again.</div>}
        <div className="row">
          <button className="btn primary" onClick={submit}>Answer</button>
          {/* Skipping counts as not-yet, which is the truthful reading: a
              skill you'd rather not attempt is not one you're secure on. */}
          <button className="btn" onClick={() => answer(false)}>Skip</button>
        </div>
      </section>
    </div>
  );
}

function Settings({ state, setState, say, onConfirmReset }) {
  const [text, setText] = React.useState("");
  const [mode, setMode] = React.useState(null);          // "export" | "import"
  const [err, setErr] = React.useState(null);

  const payload = () => JSON.stringify({ app: "slate", version: 1, savedAt: new Date().toISOString(), state: state }, null, 2);

  const doExport = () => { setMode("export"); setText(payload()); setErr(null); };

  const doDownload = () => {
    try {
      const blob = new Blob([payload()], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url; a.download = "slate-backup.json";
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      say("Backup saved.");
    } catch (e) { setErr("This browser wouldn't let me save a file. Copy the text instead."); }
  };

  const doCopy = () => {
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) { navigator.clipboard.writeText(payload()); say("Copied."); }
      else setErr("Copying isn't available here — select the text and copy it by hand.");
    } catch (e) { setErr("Copying isn't available here — select the text and copy it by hand."); }
  };

  const doImport = () => {
    setErr(null);
    let parsed;
    try { parsed = JSON.parse(text); }
    catch (e) { setErr("That isn't readable as a backup file."); return; }
    const st = parsed && (parsed.state || parsed);
    if (!st || typeof st !== "object" || typeof st.skills !== "object" || st.skills === null) {
      setErr("That file doesn't contain a Mathema record."); return;
    }
    // Only known shapes are taken in. Anything else in the file is ignored
    // rather than trusted straight into the app's state.
    const skills = {};
    Object.keys(st.skills).forEach(id => {
      if (!K.BY_ID[id]) return;
      const r = st.skills[id] || {};
      skills[id] = {
        seen: Math.max(0, Number(r.seen) || 0),
        right: Math.max(0, Number(r.right) || 0),
        top: Math.min(3, Math.max(1, Number(r.top) || 1)),
        run: Math.max(0, Number(r.run) || 0),
        last: Number(r.last) || 0
      };
      if (skills[id].right > skills[id].seen) skills[id].right = skills[id].seen;
    });
    const misses = Array.isArray(st.misses) ? st.misses.filter(m2 => m2 && K.BY_ID[m2.skill] && Number.isFinite(Number(m2.seed))).slice(-40) : [];
    const kept = Object.keys(skills).length;
    setState({ skills: skills, misses: misses, workDefault: !!st.workDefault, theme: state.theme });
    say("Restored " + kept + (kept === 1 ? " skill." : " skills."));
    setMode(null); setText("");
  };

  return (
    <div className="screen">
      <div className="hero"><h1>Settings</h1></div>

      <CloudSync state={state} setState={setState} say={say} />

      <div className="setgroup">
        <div className="setlab">Appearance</div>
        <div className="segrow">
          {[["auto", "Match device"], ["light", "Light"], ["dark", "Dark"]].map(([v, label]) => (
            <button key={v} className={"seg" + ((state.theme || "auto") === v ? " on" : "")}
              onClick={() => setState(st => ({ ...st, theme: v }))}>{label}</button>
          ))}
        </div>
      </div>

      <div className="setgroup">
        <div className="setlab">Showing your working</div>
        <label className="tgl">
          <input type="checkbox" checked={!!state.workDefault}
            onChange={e => setState(st => ({ ...st, workDefault: e.target.checked }))} />
          <span>Open the working area by default</span>
        </label>
        <div className="tglnote">You can still turn it on or off on any single question. Answering straight out is worth exactly the same either way.</div>
      </div>

      <div className="setgroup">
        <div className="setlab">Your record</div>
        <p className="setnote">Everything is kept on this device and nowhere else. There's no account, so clearing your browser data clears this too. A backup is the only copy you'll have.</p>
        <div className="segrow">
          <button className="seg" onClick={doExport}>Back up</button>
          <button className="seg" onClick={() => { setMode("import"); setText(""); setErr(null); }}>Restore</button>
        </div>

        {mode === "export" && (
          <div className="backup">
            <p className="setnote">This contains how many questions you've answered per skill, which ones you missed, and your settings. It contains no personal information and no questions.</p>
            <textarea className="bkarea" readOnly value={text} aria-label="Your backup" rows={6} />
            <div className="segrow">
              <button className="seg" onClick={doDownload}>Save as a file</button>
              <button className="seg" onClick={doCopy}>Copy</button>
              <button className="seg" onClick={() => setMode(null)}>Done</button>
            </div>
          </div>
        )}

        {mode === "import" && (
          <div className="backup">
            <p className="setnote">Paste a backup below. Restoring <strong>replaces</strong> what's on this device — it doesn't merge, and the current record is gone.</p>
            <textarea className="bkarea" value={text} rows={6} aria-label="Paste a backup"
              placeholder="paste your backup here" onChange={e => setText(e.target.value)} />
            <div className="segrow">
              <button className="seg" onClick={doImport} disabled={!text.trim()}>Restore it</button>
              <button className="seg" onClick={() => setMode(null)}>Cancel</button>
            </div>
          </div>
        )}
        {err && <div className="setwarn">{err}</div>}
      </div>

      <div className="setgroup">
        <div className="setlab">Start again</div>
        <button className="btn danger" onClick={onConfirmReset}>Clear everything on this device</button>
      </div>

      <div className="foot">
        <p>Mathema {MATHEMA_VERSION.replace(/^\d{4}-\d{2}-\d{2}-/, "")}</p>
      </div>
    </div>
  );
}


/* ---------------------------------------------------------------------------
   THE SANDBOX — "mess with it"

   Nothing here is asked, marked, timed or recorded. It exists because there is
   a kind of understanding you only get by pulling something and watching what
   moves: change one number in a quadratic and see which way the curve goes,
   make the denominator bigger and watch the pieces get smaller.

   Everything shown is computed by the same engine that grades the questions —
   the derivative is the exact symbolic one, not a numerical estimate — so
   nothing here can disagree with the rest of the app.
--------------------------------------------------------------------------- */

function Plot({ fns, from, to, marks }) {
  const W = 320, H = 210, pad = 6;
  const lo = from == null ? -6 : from, hi = to == null ? 6 : to;
  const yMax = 8;
  const X = x => pad + ((x - lo) / (hi - lo)) * (W - pad * 2);
  const Y = y => H / 2 - (y / yMax) * (H / 2 - pad);
  const paths = fns.map(f => {
    let d = "", pen = false;
    for (let i = 0; i <= 240; i++) {
      const x = lo + (hi - lo) * (i / 240);
      let y;
      try { y = S.evaluate(f.ast, { x }); } catch (e) { y = NaN; }
      if (!isFinite(y) || Math.abs(y) > yMax * 1.6) { pen = false; continue; }
      d += (pen ? " L " : " M ") + X(x).toFixed(1) + " " + Y(y).toFixed(1);
      pen = true;
    }
    return { d, cls: f.cls };
  });
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="widget" role="img" aria-label="A plot of the expression">
      {Array.from({ length: 13 }).map((_, i) => (
        <line key={"v" + i} x1={X(lo + (hi - lo) * i / 12)} y1={0} x2={X(lo + (hi - lo) * i / 12)} y2={H} className="cgrid" />
      ))}
      {[-6, -4, -2, 0, 2, 4, 6].map(y => (
        <line key={"h" + y} x1={0} y1={Y(y)} x2={W} y2={Y(y)} className="cgrid" />
      ))}
      <line x1={0} y1={Y(0)} x2={W} y2={Y(0)} className="chalk" strokeWidth="1.4" />
      <line x1={X(0)} y1={0} x2={X(0)} y2={H} className="chalk" strokeWidth="1.4" />
      {paths.map((p, i) => p.d ? <path key={i} d={p.d} className={p.cls} fill="none" /> : null)}
      {(marks || []).map((m, i) => (
        isFinite(m.x) && Math.abs(m.x) <= Math.max(Math.abs(lo), Math.abs(hi)) ? (
          <circle key={i} cx={X(m.x)} cy={Y(m.y == null ? 0 : m.y)} r={4} className="cdot pick" />
        ) : null
      ))}
    </svg>
  );
}

/* Nobody writes 1x or + 0x. */
function coef(n, sym) { return n === 1 ? sym : n === -1 ? "−" + sym : n + sym; }
function term(n, sym) {
  if (n === 0) return "";
  if (n === 1) return " + " + sym;
  if (n === -1) return " − " + sym;
  return n < 0 ? " − " + Math.abs(n) + sym : " + " + n + sym;
}
function termN(n) { return n === 0 ? "" : n < 0 ? " − " + Math.abs(n) : " + " + n; }

function Slider({ label, value, min, max, step, onChange, suffix }) {
  return (
    <div className="sliderrow">
      <div className="sllab"><span>{label}</span><b>{value}{suffix || ""}</b></div>
      <input className="slider" type="range" min={min} max={max} step={step == null ? 1 : step}
        value={value} aria-label={label}
        onChange={e => onChange(Number(e.target.value))} />
    </div>
  );
}

function PlayLine() {
  const [m, setM] = React.useState(2), [c, setC] = React.useState(1);
  const ast = React.useMemo(() => S.parse(m + "*x + (" + c + ")"), [m, c]);
  return (
    <div className="playcard">
      <div className="playtitle">Straight lines</div>
      <div className="playeq">y = {coef(m, "x")}{termN(c)}</div>
      <Plot fns={[{ ast, cls: "ccurve" }]} marks={[{ x: 0, y: c }, { x: m !== 0 ? -c / m : NaN, y: 0 }]} />
      <Slider label="gradient m" value={m} min={-5} max={5} onChange={setM} />
      <Slider label="intercept c" value={c} min={-6} max={6} onChange={setC} />
      <div className="playnote">
        {m === 0 ? "With m at zero the line is flat — no rise for any run."
          : "For every 1 across, it goes " + Math.abs(m) + " " + (m > 0 ? "up" : "down") + ". It crosses the y-axis at " + c +
          " and the x-axis at " + S.numText(Math.round(-c / m * 100) / 100) + "."}
      </div>
    </div>
  );
}

function PlayQuadratic() {
  const [a, setA] = React.useState(1), [b, setB] = React.useState(0), [c, setC] = React.useState(-4);
  const src = a + "*x^2 + (" + b + ")*x + (" + c + ")";
  const ast = React.useMemo(() => S.parse(src), [src]);
  const disc = b * b - 4 * a * c;
  const roots = React.useMemo(() => {
    if (a === 0) return b === 0 ? [] : [-c / b];
    if (disc < 0) return [];
    const r = Math.sqrt(disc);
    return disc === 0 ? [-b / (2 * a)] : [(-b - r) / (2 * a), (-b + r) / (2 * a)];
  }, [a, b, c, disc]);
  const vx = a === 0 ? null : -b / (2 * a);
  return (
    <div className="playcard">
      <div className="playtitle">Curves</div>
      <div className="playeq">y = {coef(a, "x²")}{term(b, "x")}{termN(c)}</div>
      <Plot fns={[{ ast, cls: "ccurve" }]}
        marks={roots.map(r => ({ x: r, y: 0 })).concat(vx == null ? [] : [{ x: vx, y: a * vx * vx + b * vx + c }])} />
      <Slider label="a" value={a} min={-3} max={3} onChange={setA} />
      <Slider label="b" value={b} min={-6} max={6} onChange={setB} />
      <Slider label="c" value={c} min={-6} max={6} onChange={setC} />
      <div className="playnote">
        {a === 0
          ? "With a at zero there is no x² term left, so it isn't a curve at all — it's a straight line."
          : "b² − 4ac is " + disc + ", so it crosses the x-axis " +
          (disc > 0 ? "twice, at " + roots.map(r => S.numText(Math.round(r * 100) / 100)).join(" and ")
            : disc === 0 ? "once, where it just touches" : "nowhere") +
          ". The turning point sits at x = " + S.numText(Math.round(vx * 100) / 100) + "."}
      </div>
    </div>
  );
}

function PlayFraction() {
  const [parts, setParts] = React.useState(4), [filled, setFilled] = React.useState(3);
  const f = Math.min(filled, parts);
  const g = S.gcd(f, parts) || 1;
  return (
    <div className="playcard">
      <div className="playtitle">Fractions</div>
      <div className="playeq">{f}/{parts}</div>
      <FractionBar spec={{ parts, filled: f }} onPick={v => setFilled(v)} picked={null} />
      <Slider label="pieces the whole is cut into" value={parts} min={1} max={16}
        onChange={v => { setParts(v); if (filled > v) setFilled(v); }} />
      <Slider label="pieces taken" value={f} min={0} max={parts} onChange={setFilled} />
      <div className="playnote">
        That's {S.numText(Math.round(f / parts * 1000) / 1000)} as a decimal
        {g > 1 ? ", and it simplifies to " + (f / g) + "/" + (parts / g) + " because both divide by " + g + "." : ", and it won't simplify any further."}
        {" "}Cutting the whole into more pieces makes each piece smaller, not the amount bigger.
      </div>
    </div>
  );
}

function PlayRectangle() {
  const [w, setW] = React.useState(6), [h, setH] = React.useState(4);
  return (
    <div className="playcard">
      <div className="playtitle">Rectangles and products</div>
      <div className="playeq">{w} × {h} = {w * h}</div>
      <AreaModel spec={{ w, h, product: w * h }} revealed={true} />
      <Slider label="across" value={w} min={1} max={12} onChange={setW} />
      <Slider label="down" value={h} min={1} max={12} onChange={setH} />
      <div className="playnote">
        Turning it on its side makes it {h} across and {w} down, and it still holds {w * h} squares — which is why
        {" "}{w} × {h} and {h} × {w} give the same answer.
      </div>
    </div>
  );
}

function PlayExpression() {
  const [text, setText] = React.useState("x^2");
  const parsed = React.useMemo(() => S.tryParse(text), [text]);
  const info = React.useMemo(() => {
    if (!parsed.ok) return null;
    const vars = S.varList(parsed.ast);
    if (vars.length > 1) return { tooMany: vars };
    if (!vars.length) {
      let v = null;
      try { v = S.evaluate(parsed.ast, {}); } catch (e) { }
      return { constant: v };
    }
    let d = null;
    try { d = S.simplify(S.derive(parsed.ast, vars[0])); } catch (e) { }
    return { v: vars[0], d };
  }, [parsed]);

  const table = React.useMemo(() => {
    if (!parsed.ok || !info || !info.v) return [];
    return [-2, -1, 0, 1, 2, 3].map(x => {
      let y;
      try { y = S.evaluate(parsed.ast, { [info.v]: x }); } catch (e) { y = NaN; }
      return { x, y: isFinite(y) ? S.numText(Math.round(y * 1000) / 1000) : "—" };
    });
  }, [parsed, info]);

  return (
    <div className="playcard">
      <div className="playtitle">Anything you like</div>
      <input className="ans playinput" value={text} onChange={e => setText(e.target.value)}
        aria-label="An expression to explore" spellCheck={false} autoComplete="off" />
      {!parsed.ok && <div className="playnote bad">I can't read that: {parsed.error}</div>}
      {parsed.ok && info && info.tooMany && (
        <div className="playnote">That has {info.tooMany.length} different letters in it ({info.tooMany.join(", ")}), so there's nothing single to plot.</div>
      )}
      {parsed.ok && info && info.constant !== undefined && (
        <div className="playnote">No letters in it, so it's just a number: {S.numText(info.constant)}.</div>
      )}
      {parsed.ok && info && info.v && (
        <>
          <Plot fns={[{ ast: parsed.ast, cls: "ccurve" }].concat(info.d ? [{ ast: info.d, cls: "cline" }] : [])} />
          <div className="playlegend">
            <span><i className="swatch curve" /> {S.print(parsed.ast)}</span>
            {info.d && <span><i className="swatch line" /> its derivative, {S.print(info.d)}</span>}
          </div>
          <div className="ptable">
            {table.map(row => (
              <div className="pcol" key={row.x}><b>{row.x}</b><span>{row.y}</span></div>
            ))}
          </div>
          <div className="playnote">
            The derivative is worked out exactly, by the same code the questions use — not estimated from the picture.
          </div>
        </>
      )}
    </div>
  );
}

const PLAYS = [
  { id: "rect", name: "Rectangles and products", strand: "Number", make: () => <PlayRectangle /> },
  { id: "frac", name: "Fractions", strand: "Fractions", make: () => <PlayFraction /> },
  { id: "line", name: "Straight lines", strand: "Algebra", make: () => <PlayLine /> },
  { id: "quad", name: "Curves", strand: "Algebra", make: () => <PlayQuadratic /> },
  { id: "expr", name: "Anything you like", strand: "Calculus", make: () => <PlayExpression /> }
];

function Playground({ which, onPick }) {
  const active = PLAYS.find(p => p.id === which) || PLAYS[0];
  return (
    <div className="screen">
      <div className="hero">
        <h1>Mess with it</h1>
        <p>Pull things and watch what moves. Nothing here is asked, marked or recorded — there's no wrong answer to find, because nothing is being asked.</p>
      </div>
      <div className="playtabs">
        {PLAYS.map(p => (
          <button key={p.id} className={"lpip" + (p.id === active.id ? " on" : "")}
            onClick={() => onPick(p.id)}>{p.name}</button>
        ))}
      </div>
      {active.make()}
    </div>
  );
}

/* ---------------------------------------------------------------------------
   HOME — the map. Skills are grouped by strand and show what they lean on,
   because "you're missing this because you haven't done fractions" is a more
   useful thing to hear than a percentage.
--------------------------------------------------------------------------- */
function Home({ state, onOpen, onLearn, onPractice, onReview }) {
  const strands = K.strands();
  const [query, setQuery] = React.useState("");
  const q = query.trim().toLowerCase();
  // Search covers method names too, because "column method" or "chunking" is
  // often what someone is actually looking for, not the skill's title.
  const matches = sk => {
    if (!q) return true;
    const methods = (K.levelsOf(sk.id) || []).map(l => l.method).join(" ");
    return (sk.name + " " + sk.strand + " " + methods).toLowerCase().indexOf(q) >= 0;
  };
  const due = React.useMemo(() => dueSkills(state), [state]);
  const rec = React.useMemo(() => {
    // The shakiest skill whose groundwork is already solid — that's the one
    // worth doing next, and the reason is stated rather than scored.
    let best = null;
    K.SKILLS.forEach(sk => {
      const st = state.skills[sk.id] || { seen: 0, right: 0 };
      const needsOk = (sk.needs || []).every(n => {
        const p = state.skills[n];
        return p && p.seen >= 2 && p.right / p.seen >= 0.6;
      });
      if (!needsOk) return;
      const rate = st.seen ? st.right / st.seen : 0;
      const score = st.seen === 0 ? 0.5 : 1 - rate;
      if (!best || score > best.score) best = { sk, score, st };
    });
    return best;
  }, [state]);

  return (
    <div className="screen">
      <div className="hero">
        <h1>Mathema</h1>
        <p>Math from counting on to calculus. Learn a method properly, or jump straight in and have the explanation land on what you actually did — both doors are open on every skill.</p>
      </div>
      <div className="searchrow">
        <input className="search" value={query} onChange={e => setQuery(e.target.value)}
          placeholder="Search skills and methods" aria-label="Search skills and methods"
          inputMode="search" autoComplete="off" spellCheck={false} />
        {query && <button className="clearq" onClick={() => setQuery("")} aria-label="Clear search">×</button>}
      </div>

      {!q && due.length > 0 && (
        <button className="cont due" onClick={() => onReview(due[0].sk.id)}>
          <div className="ct1">Due for review</div>
          <div className="ct2">{due.length === 1 ? due[0].sk.name : due.length + " skills"}</div>
          <div className="ct3">
            {due.length === 1
              ? "Last done " + agoLabel(Date.now() - due[0].rec.last) + " ago, and it was set to come back after " + due[0].info.days + (due[0].info.days === 1 ? " day." : " days.")
              : "Starting with " + due[0].sk.name + ", left longest."}
          </div>
        </button>
      )}

      {!q && (
        <button className="cont" onClick={onPractice}>
          <div className="ct1">Practice</div>
          <div className="ct2">A run of ten</div>
          <div className="ct3">It moves you up a tier when you're ready, and teaches the new method first.</div>
        </button>
      )}

      {rec && !q && (
        <button className="cont" onClick={() => onOpen(rec.sk.id)}>
          <div className="ct1">{(state.skills[rec.sk.id] || {}).seen ? "Worth another look" : "Start here"}</div>
          <div className="ct2">{rec.sk.name}</div>
          <div className="ct3">
            {(state.skills[rec.sk.id] || {}).seen
              ? "You've got " + (state.skills[rec.sk.id].right) + " of " + state.skills[rec.sk.id].seen + " right here so far."
              : (rec.sk.needs || []).length ? "Everything this leans on is holding up." : "It doesn't lean on anything else."}
          </div>
        </button>
      )}

      {q && K.SKILLS.filter(matches).length === 0 && (
        <div className="nores">Nothing matches “{query}”. Try a method name like “chunking” or a topic like “fractions”.</div>
      )}

      {strands.filter(str => K.SKILLS.some(sk => sk.strand === str && matches(sk))).map(str => (
        <div key={str}>
          <div className="secttl">{str}</div>
          <div className="grid">
            {K.SKILLS.filter(s => s.strand === str && matches(s)).map(sk => {
              const st = state.skills[sk.id];
              const locked = (sk.needs || []).filter(n => {
                const p = state.skills[n];
                return !(p && p.seen >= 2 && p.right / p.seen >= 0.6);
              });
              return (
                <div key={sk.id} className={"skill" + (st && st.seen ? " started" : "")}>
                  <div className="sname">{sk.name}</div>
                  <div className="smeta">
                    {st && st.seen
                      ? st.right + " of " + st.seen + " right"
                      : locked.length
                        ? "leans on " + locked.map(n => K.BY_ID[n].name.toLowerCase()).join(", ")
                        : "not started"}
                  </div>
                  <div className="smeth">{(K.levelsOf(sk.id) || []).map(l2 => l2.method).join(" → ")}</div>
                  {st && st.seen > 0 && (
                    <div className="sbar"><i style={{ width: Math.round(st.right / st.seen * 100) + "%" }} /></div>
                  )}
                  <div className="sdoors">
                    <button className="sdoor" onClick={() => onLearn(sk.id)}>Teach me</button>
                    <button className="sdoor go" onClick={() => onOpen(sk.id)}>Practice</button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}

      <div className="foot">
        <p>Nothing here is graded on how you got there. Any correct form of a correct answer is correct.</p>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------------------
   ROOT
--------------------------------------------------------------------------- */
function MathemaApp() {
  const [state, setState] = React.useState(() => {
    const s = loadState();
    return { skills: s.skills || {}, misses: s.misses || [], workDefault: !!s.workDefault, theme: s.theme || "auto" };
  });
  React.useEffect(() => { saveState(state); }, [state]);

  const [route, setRoute] = React.useState(() => parseRoute(typeof window !== "undefined" ? window.location.hash : ""));
  const [dir, setDir] = React.useState("fade");
  const [sheet, setSheet] = React.useState(null);
  const [toast, setToast] = React.useState(null);
  const depthRef = React.useRef(route.depth);

  // Back and forward are the platform's, not ours. Listening to the hash means
  // the phone's back gesture and the browser's button both do the obvious thing.
  React.useEffect(() => {
    if (typeof window === "undefined") return;
    const onHash = () => {
      const next = parseRoute(window.location.hash);
      // Back sets the parent screen immediately, so the event that follows often
      // reports where we already are. Re-rendering for that would replay the
      // transition animation for no reason.
      setRoute(cur => {
        if (JSON.stringify(cur) === JSON.stringify(next)) return cur;
        setDir(next.depth > depthRef.current ? "fwd" : next.depth < depthRef.current ? "back" : "fade");
        depthRef.current = next.depth;
        return next;
      });
    };
    window.addEventListener("hashchange", onHash);
    return () => window.removeEventListener("hashchange", onHash);
  }, []);

  const go = React.useCallback((rawPath, opts) => {
    const path = withBase(rawPath);
    const next = parseRoute(path);
    setDir(next.depth > depthRef.current ? "fwd" : next.depth < depthRef.current ? "back" : "fade");
    depthRef.current = next.depth;
    setRoute(next);                       // immediate, so the UI never waits on the event
    if (typeof window === "undefined" || window.location.hash === path) return;
    // Some moves are a change of view rather than a journey — switching between
    // the methods of one skill is a segmented control, not a new screen. Those
    // replace the entry, so Back leaves the skill instead of walking backwards
    // through every method you looked at.
    if (opts && opts.replace) window.location.replace(path);
    else window.location.hash = path;
  }, []);

  // Back pops real history, so the phone's back gesture and the browser button
  // behave the same. The parent screen is also set immediately rather than
  // waiting on the hashchange event, so the interface never sits on the old
  // screen for a frame; whatever history reports afterwards wins.
  const parentPath = r2 => r2.tab === "practice" ? "#/practice" : r2.tab === "progress" ? "#/progress" : "#/";
  const back = React.useCallback(() => {
    if (route.depth === 0) return;
    const parent = parseRoute(parentPath(route));
    setDir("back");
    depthRef.current = parent.depth;
    setRoute(parent);
    if (typeof window !== "undefined" && window.history.length > 1) window.history.back();
    else if (typeof window !== "undefined") window.location.hash = parentPath(route);
  }, [route]);

  const say = React.useCallback(msg => {
    setToast(msg);
    setTimeout(() => setToast(t2 => (t2 === msg ? null : t2)), 2400);
  }, []);

  const mark = React.useCallback((skillId, right, seed, difficulty) => {
    setState(st => {
      const cur = st.skills[skillId] || { seen: 0, right: 0, top: 1, run: 0 };
      let misses = (st.misses || []).filter(m2 => !(m2.skill === skillId && m2.seed === seed));
      if (!right) misses = misses.concat([{ skill: skillId, seed, difficulty, at: Date.now() }]).slice(-40);
      return {
        ...st, misses,
        skills: {
          ...st.skills,
          [skillId]: {
            seen: cur.seen + 1, right: cur.right + (right ? 1 : 0),
            top: Math.max(cur.top || 1, difficulty || 1), last: Date.now(),
            // A run of correct answers stretches the gap before it comes back;
            // one miss puts it back to the start, because that's what the
            // evidence says about whether it has stuck.
            run: right ? (cur.run || 0) + 1 : 0
          }
        }
      };
    });
  }, []);

  const diagnose = React.useCallback(skillId => {
    const chain = K.prereqChain(skillId);
    let worst = null;
    chain.forEach(id => {
      const st = state.skills[id], sk = K.BY_ID[id];
      if (!sk) return;
      if (!st || st.seen === 0) {
        if (!worst || worst.rate > -1) worst = { id, name: sk.name, rate: -1, why: "you haven't tried that yet" };
        return;
      }
      const rate = st.right / st.seen;
      if (rate >= 0.7) return;
      if (!worst || (worst.rate >= 0 && rate < worst.rate))
        worst = { id, name: sk.name, rate, why: "you've got " + st.right + " of " + st.seen + " right there" };
    });
    return worst;
  }, [state]);

  // A question's seed lives in component state rather than the URL, so that
  // "next question" doesn't bury the back button under twenty history entries.
  //
  // Its DIFFICULTY is frozen at the moment the question is handed over, and this
  // matters more than it looks. Recomputing it during render meant that marking
  // an answer could change the difficulty, which changed the question, which
  // wiped the verdict the learner had just earned — their correct answer
  // vanished in front of them. A question must not change while it is being
  // answered.
  const stateRef = React.useRef(state); stateRef.current = state;
  const difficultyNow = skillId => {
    const st = stateRef.current.skills[skillId];
    if (!st || st.seen < 3) return 1;
    const rate = st.right / st.seen;
    return rate > 0.85 ? 3 : rate > 0.6 ? 2 : 1;
  };
  const [question, setQuestion] = React.useState(() => ({ seed: (Date.now() % 100000) + 1, difficulty: 1 }));
  const freshQuestion = skillId => setQuestion({ seed: (Date.now() % 100000) + 1, difficulty: difficultyNow(skillId) });
  const nextQuestion = () => setQuestion(q2 => ({
    seed: (q2.seed * 7919 + 13) % 100000 + 1,
    difficulty: difficultyNow(route.skillId)
  }));

  React.useEffect(() => {
    if (typeof document === "undefined") return;
    const sk = route.skillId ? K.BY_ID[route.skillId] : null;
    document.title = route.name === "map" ? "Mathema"
      : route.name === "practice" ? "Practice · Mathema"
        : route.name === "progress" ? "Progress · Mathema"
          : route.name === "session" ? "Practice · Mathema"
            : sk ? sk.name + " · Mathema" : "Mathema";
  }, [route]);

  // Native-app trimmings: status-bar color, safe areas, no double-tap zoom.
  React.useEffect(() => {
    if (typeof document === "undefined") return;
    const set = (name, content, attr) => {
      let el = document.querySelector("meta[" + (attr || "name") + "='" + name + "']");
      if (!el) { el = document.createElement("meta"); el.setAttribute(attr || "name", name); document.head.appendChild(el); }
      el.setAttribute("content", content);
    };
    set("viewport", "width=device-width, initial-scale=1, viewport-fit=cover, maximum-scale=1");
    // Two colors, so the status bar matches whichever way the device is set.
    set("theme-color", "#f3f5f5");
    let dm = document.querySelector("meta[name='theme-color'][media]");
    if (!dm) {
      dm = document.createElement("meta");
      dm.setAttribute("name", "theme-color");
      dm.setAttribute("media", "(prefers-color-scheme: dark)");
      document.head.appendChild(dm);
    }
    dm.setAttribute("content", "#0f1516");
    set("apple-mobile-web-app-capable", "yes");
    set("apple-mobile-web-app-status-bar-style", "default");
    set("color-scheme", "light dark");
  }, []);

  const resetSheet = {
    title: "Clear everything on this device?",
    body: "This removes every skill's record and every missed question kept here. The questions themselves aren't stored, so nothing else is lost, and it can't be undone. If you want to keep it, back it up first in Settings.",
    confirmLabel: "Clear it", danger: true,
    onConfirm: () => { setState(st => ({ skills: {}, misses: [], workDefault: false, theme: st.theme })); setSheet(null); say("Cleared."); }
  };

  const showTabs = route.depth === 0;
  const openSkill = id => go("#/skill/" + id);
  const openLearn = (id, level) => go("#/learn/" + id + "/" + (level || 0));

  let body = null;
  if (route.name === "map") {
    body = <Home state={state} onOpen={id => { freshQuestion(id); openSkill(id); }}
      onLearn={openLearn} onPractice={() => go("#/practice")}
      onReview={id => { freshQuestion(id); openSkill(id); }} />;
  } else if (route.name === "practice") {
    body = <PracticeHome aiAvailable={false} onStart={scope => go("#/session/" + encodeURIComponent(scope))}
      onCheck={() => go("#/check")} />;
  } else if (route.name === "play") {
    body = <Playground which={route.which} onPick={id => go("#/play/" + id, { replace: true })} />;
  } else if (route.name === "check") {
    body = <Workbench />;
  } else if (route.name === "placement") {
    body = <Placement state={state} setState={setState} onExit={() => go("#/progress")} onOpen={openSkill} />;
  } else if (route.name === "settings") {
    body = <Settings state={state} setState={setState} say={say} onConfirmReset={() => setSheet(resetSheet)} />;
  } else if (route.name === "progress") {
    body = <Progress state={state}
      onOpen={openSkill}
      onOpenMiss={m2 => go("#/review/" + m2.skill + "/" + m2.seed + "/" + m2.difficulty)}
      onPlacement={() => go("#/placement")}
      onSettings={() => go("#/settings")}
      onReset={() => setSheet(resetSheet)} />;
  } else if (route.name === "session") {
    body = <Session scope={route.scope} startDifficulty={1} mark={mark} onExit={back} />;
  } else if (route.name === "learn") {
    body = <Learn skillId={route.skillId} level={route.level || 0}
      onLevel={i => go("#/learn/" + route.skillId + "/" + i, { replace: true })}
      onPractise={d => { setQuestion({ seed: (Date.now() % 100000) + 1, difficulty: d }); go("#/skill/" + route.skillId); }}
      onExit={back} />;
  } else if (route.name === "skill") {
    body = <Practice
      skillId={route.skillId}
      seed={route.review ? route.seed : question.seed}
      difficulty={route.review ? route.difficulty : question.difficulty}
      isReview={!!route.review}
      onDone={nextQuestion} onExit={back} mark={mark}
      diagnose={diagnose} onOpenSkill={openSkill} onLearnThis={openLearn}
      workDefault={state.workDefault}
      setWorkDefault={v => setState(st => ({ ...st, workDefault: v }))} />;
  }

  const sk = route.skillId ? K.BY_ID[route.skillId] : null;
  const heading = route.name === "practice" || route.name === "session" ? "Practice"
    : route.name === "progress" ? "Progress"
      : route.name === "play" ? "Mess with it"
        : route.name === "placement" ? "Where to start"
        : route.name === "settings" ? "Settings"
          : route.name === "check" ? "Check my working"
            : sk ? sk.name : "Mathema";

  return (
    <div className={"app" + (showTabs ? " tabbed" : "")} data-theme={state.theme || "auto"}>
      <style>{CSS}</style>
      <div className="appbar">
        {route.depth > 0
          ? <button className="navback" onClick={back} aria-label="Back"><Icon d="M15 5l-7 7 7 7" size={19} /></button>
          : <div className="mk" aria-hidden="true"><Mark size={17} /></div>}
        <div className="ti">{heading}</div>
      </div>
      <div className={"scroll " + dir} key={route.name + (route.skillId || "") + (route.level || "")}>
        {body}
      </div>
      {showTabs && <TabBar active={route.tab} go={go} />}
      <Sheet open={!!sheet} {...(sheet || {})} onClose={() => setSheet(null)} />
      <Toast text={toast} />
    </div>
  );
}


/* `base` is the route prefix. The hub passes "math"; standalone it is empty.
   Set before any state initialises, because parseRoute runs during the first
   render and must already know the prefix. */
export default function Mathema({ base } = {}) {
  setRouteBase(base);
  return <MathemaApp />;
}

export { S as MathemaEngine, K as MathemaSkills, SOLVER as MathemaSolver, MATHEMA_VERSION };
